INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('leisure-suit-larry-6-shape-up-or-slip-out', 2911, '1993-06-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xnz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arq6b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leisure Suit Larry 6: Shape Up or Slip Out!', 'Shape Up or Slip Out! is the fifth game in Al Lowe''s Leisure Suit Larry series. All the events from the previous games are forgotten. Larry is once again single, and again his goal is to capture the interest of various ladies. By sheer coincidence, Larry finds himself on a TV Game Show called "Stallions". He wins a weekend at the Spa Resort, La Costa Lotta. Naturally, there are some beautiful women in the spa who are just dreaming about such a wonderful, handsome man as Larry! Uh... or is it really so? It is the player''s goal to find out! This instalment focuses more on conversations with women and puzzles than on the storyline. The entire game is spent at La Costa Lotta. There are plenty of traditional inventory-based puzzles to solve in the game. Larry can die, but the player is allowed to try again every time that happens, without the need to restore a saved game. This is also the first Larry game with SVGA graphics, and voice-overs in the CD version.' FROM games WHERE igdb_id = 2911 ON CONFLICT (game_id, language_code) DO NOTHING;
