INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Master: Kyuukyoku no Senshi-tachi', 'Battle Master: Kyuukyoku no Senshi-tachi ("Battle Master: Ultimate Warrior") is a sci-fi themed one-on-one fighter game exclusively for the Super Famicom. It was developed by System Vision, which previously worked on the SNES fighter Deadly Moves. The player can select between seven characters and play through a single-player mode with each, meeting different opponents and fighting a boss character at the end. There''s also a Versus mode that allows two human players to compete with fighters of their choice.' FROM games WHERE igdb_id = 42281 ON CONFLICT (game_id, language_code) DO NOTHING;
