INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Warrior', 'The gameplay of Blood Warrior is quite similar to many of the 2D fighting games of the same era. However, Kaneko seem to have taken much of their inspiration from the Mortal Kombat franchise in terms of over the top gore and violence; however, Blood Warrior''s predecessor Shogun Warriors predates Mortal Kombat in featuring blood, while Barbarian: The Ultimate Warrior predates Mortal Kombat in featuring death moves.' FROM games WHERE igdb_id = 39559 ON CONFLICT (game_id, language_code) DO NOTHING;
