INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nyet 3: Revenge of the Mutant Stones', 'Nyet 3: Revenge of the Mutant Stones is a Tetris variant written by Proline software. It consists of upto 108 stages, all based on the Tetris ruleset. The objective is to clear a set number of lines within the stage, but each has a twist in the ruleset discovered during play.' FROM games WHERE igdb_id = 18631 ON CONFLICT (game_id, language_code) DO NOTHING;
