INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('might-and-magic-v-darkside-of-xeen', 7737, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4oz4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30ro.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Might and Magic V: Darkside of Xeen', 'Might and Magic V: Darkside of Xeen (originally released as Might and Magic: Darkside of Xeen) is a science fantasy role-playing video game, published and developed for multiple platforms by New World Computing in 1993. Based on the Might and Magic III: Isles of Terra game engine, it is the fifth game in the Might and Magic series, and is a direct sequel to Might and Magic IV: Clouds of Xeen, concluding the story arc started in the original Might and Magic Book One: The Secret of the Inner Sanctum. Like its predecessors, it was well received by both critics and players for its large game world and graphics, and was among the earliest games to make use of both animated cutscenes and PCM sound-based speech. Its unique integration mechanic with the game world of Clouds of Xeen, allowing both games to be played in a combined format - World of Xeen - was considered revolutionary at the time.' FROM games WHERE igdb_id = 7737 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 7737 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
