INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('transarctica', 10857, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29m7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8bki.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transarctica', 'The story is based on a post-apocalyptic science fiction saga La Compagnie des Glaces (The Ice Company) written by Georges-Jean Arnaud and the comic strip Le Transperceneige (The Snowpiercer) by Jacques Lob.  In the 21st century, mankind is being ravaged by the greenhouse effect. A last-ditch effort to counteract it is designed and executed. It works far too well.  Centuries if not millennia later, the planet is entirely covered in a thick, opaque cloud layer. Giant wolf packs roam the frozen wastes, and the mammoth has re-emerged from the elephant stock. Mankind ekes out a living in a few handfuls of settlements, connected by a network of massive armored trains. The network in turn is in the hands of the gargantuan Viking Union, which is merciless towards threats to its power. A few radicals, though, are willing to attempt a change, and managing to hijack a train of the Union, the Transarctica, they set out in search of the "sun".' FROM games WHERE igdb_id = 10857 ON CONFLICT (game_id, language_code) DO NOTHING;
