INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kikuni Masahiko no Jantoushi Dora-ou 2', 'Kikuni Masahiko no Jantoushi Dora Ou 2 is a mahjong game with a parody supernatural superhero theme. Like its predecessor, it uses mahjong as a sort of component for its "battle" system. Kikuni Masahiko no Jantoushi Dora Ou 2 is a bit more "free", allowing the player to explore the world map. It also allows for four-person games, removing the two-person limitation of its forebear.' FROM games WHERE igdb_id = 37961 ON CONFLICT (game_id, language_code) DO NOTHING;
