INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xak: The Art of Visual Stage', 'The Super Famicom remake of Xak: The Art of Visual Stage reworks the classic RPG for Super Famicom, replacing the original’s bump-based battles with a new sword-swinging combat system. The player assumes the role of Latok Kart, a blue-haired swordsman and the son of the legendary warrior Dork Kart. He is sent on a quest to defeat the warmongering demons led by the powerful Badu that are running rampant in the eponymous world of the humans, Xak.' FROM games WHERE igdb_id = 377091 ON CONFLICT (game_id, language_code) DO NOTHING;
