INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ToeJam & Earl in Panic on Funkotron', 'ToeJam & Earl in Panic on Funkotron is a platform video game, developed by Johnson Voorsanger Productions and published by Sega originally in 1993. The game concerns two alien protagonists, ToeJam and Earl, both of whom have escaped from Earth, where they had crash landed. After returning to their home planet of Funkotron, the duo discover a number of antagonistic Earthlings have stowed away on the spacecraft and are wreaking havoc across the planet. The player must hunt down these Earthlings and imprison them in jars before sending them back to Earth.' FROM games WHERE igdb_id = 11123 ON CONFLICT (game_id, language_code) DO NOTHING;
