INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jim Power: The Lost Dimension in 3D', 'JIm Power: The Lost Dimension in 3-D utilizes the revolutionary Nuoptix 3D graphics, allowing you to experience the thrill of virtual reality without a virtual reality system. 3D glasses facilitate the incredible depth experience, but the thrill and the horror of "The Lost Dimension" may be fully experienced with or without 3D glasses.' FROM games WHERE igdb_id = 42606 ON CONFLICT (game_id, language_code) DO NOTHING;
