INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fields of Glory', 'Originally released in 1993, this historical combat simulation deals with the wars of Napoleon after his return from exile in Elba in 1815. The game is close to historical facts and therefore can be recommended to provide good information about this period of European history.' FROM games WHERE igdb_id = 37111 ON CONFLICT (game_id, language_code) DO NOTHING;
