INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Trouble', 'Bubble Trouble is a 1994 action-adventure scrolling shooter video game developed by Lore Design Limited and published by Telegames in North America and Europe exclusively for the Atari Lynx. In the game, the players assume the role of Travis, a scientist whose experiments go wrong as he becomes trapped in a bubble world.' FROM games WHERE igdb_id = 40836 ON CONFLICT (game_id, language_code) DO NOTHING;
