INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cool Spot', 'Cool Spot is a mascot for 7 Up, introduced in 1987. During this time, the red spot in the 7 Up logo was anthropomorphized: given arms, legs, a mouth, and sunglasses. British video games developer Virgin Interactive''s American studio produced a platform game starring the 7 Up Spot, entitled Cool Spot.' FROM games WHERE igdb_id = 2621 ON CONFLICT (game_id, language_code) DO NOTHING;
