INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Baseball', 'Battle Baseball is a Japan-only baseball video game developed by Vic Tokai and published by Banpresto for the Famicom on February 19, 1993. A part of the collaborative "Compati Sports Series" (コンパチスポーツシリーズ Konpachi Supōtsu Shirīzu) in the Compati Hero series, it crosses over characters from several popular Japanese franchises, including Godzilla, Ultraman, Kamen Rider and Gundam.' FROM games WHERE igdb_id = 218826 ON CONFLICT (game_id, language_code) DO NOTHING;
