INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('winning-post', 4240, '1993-01-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40bp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/q8nwfiubqe1h0szri7nn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winning Post', 'Winning Post lets the player take control of a stable of horse, breeding and training them for the ultimate goal, to win the French Grand Prix. The player can hire breeders, trainers and jockeys and race in over 240 different races to earn more money to buy even better personnel and breed faster and stronger horses as well as keeping their horses healthy. Players can also bet on races as well. The gameplay consists of choosing options before races, such as choosing which horses to train and what regiment they undertake, view stats, hire personnel and place bets. However the player has no controls over races and cannot participate and only view as a spectator.' FROM games WHERE igdb_id = 4240 ON CONFLICT (game_id, language_code) DO NOTHING;
