INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spinmaster', 'Spinmaster is a platform/beat ''em up arcade game developed and released by Data East in 1993. The story follows the main character Johnny and his sidekick Tom as they battle their way through treasure-seeking, mad scientist, Dr. De Playne''s henchmen in a quest to save Johnny''s girlfriend Mary and get their hands on a hidden treasure. Both playable characters are armed with yo-yos but can also upgrade to other weapons (such as throwing stars, icicle daggers and guided missiles) to defeat all enemies and help them open treasure chests.' FROM games WHERE igdb_id = 15469 ON CONFLICT (game_id, language_code) DO NOTHING;
