INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ys-iv-mask-of-the-sun', 15451, '1993-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cmu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm39q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys IV: Mask of the Sun', 'After having defeated the ultimate evil in his previous adventure, the great hero Adol stands on a sea shore, thinking about the fate of the once peaceful Utopian land of Ys, while the wind is blowing through his red hair. Suddenly, Adol notices a bottle, thrown onto the shore. It contains a letter, written in a foreign language, in which an unknown person asks Adol to come to his land and save it from a mysterious evil. Adol decides to accept the offer, and thus his adventure begins again... Ys IV: Mask of the Sun is an action RPG with a combat system like the earlier Ys games. An enemy should be rammed from the sides in order to hurt him. If performed incorrectly, the player will get hurt himself. It''s also possible to use magic and position oneself strategically in battle so that the enemy won''t be able to inflict any damage.' FROM games WHERE igdb_id = 15451 ON CONFLICT (game_id, language_code) DO NOTHING;
