INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Azure', 'In this near-future 3D first-person action shooter, you play a gun for hire, piloting a bipedal mech to tear down the enemy frontlines. Your missions involve on-rails segments where you shoot foes using a reticule, plus off-rails maze exploration with combat and collectibles. Can you survive this mechanized war, protect your companions, and seize victory?' FROM games WHERE igdb_id = 233339 ON CONFLICT (game_id, language_code) DO NOTHING;
