INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('allo-allo-cartoon-fun', 14249, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lwyfdfjhsnhu93lxh7lp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bcwfnho3nujeuhtozelx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '''Allo ''Allo! Cartoon Fun!', '''Allo ''Allo is based on the long-running BBC TV comedy series set in occupied France in World War II. From the back of the box: This is without doubt one of the best platform arcade romps to come to your computer. Packed with madcap humour, action and addictive gameplay. Huge multilevels! Full 360 Multi-directional scrolling! Over 900K of stereo music and sound effects! The most spacious sound around! Fully animated backgrounds some with 8 layers of parallax! 1 or 2 players (2 player option has simultaneous gameplay) Difference game variations for 1 or 2 player options Lots and lots of cartoon characters each with their own humorous styles Well over 1 meg. of stunning graphics So come on! Join our heroes on their quest to find both fake and genuine lost art treasures in this wacky cartoon caper!' FROM games WHERE igdb_id = 14249 ON CONFLICT (game_id, language_code) DO NOTHING;
