INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('war-torn-versnag', 284073, '1993-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7obt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq95p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War-Torn Versnag', '30 years after the first Versnag War, conflict again threatens to erupt between the Anchis Empire and the bordering kingdom of Zenarg. As they head towards the precipice, two adventurers—young stalwart Zalek and plucky veteran Kinissh—get caught in the chaos. They soon realize the war''s scope extends far beyond the mortal coil, with rumors of a primordial dragon''s return looming upon the realm. Elsewhere, Zalek''s mentor Rommel asks his other disciple, Ron, to join the duo, while Princess Eve of the religious capital Romo learns about her true powers. It''s up to them and others to thwart Anchis'' new king and stop the dark one''s revival. War-Torn Versnag is a heavily story-driven JRPG divided into chapters. You play Zalek and other party members as they wander between towns, dungeons, and other locations to do battle and advance the plot. Combat normally plays out automatically, but players can tweak characters'' behaviors or manually control them as well. The game uses mouse-based controls, a rarity for X68000 exclusives; it released after much delay, late into the system''s lifecycle.' FROM games WHERE igdb_id = 284073 ON CONFLICT (game_id, language_code) DO NOTHING;
