INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Showdown', 'The final entry in Electronic Arts'' basketball series based on the old NBA playoffs engine before the NBA Live series took over. For the first time, the game features all 27 NBA teams from the 1993-1994 season. You can now play a full season with 82 games in addition to playoffs and exhibition games.' FROM games WHERE igdb_id = 45573 ON CONFLICT (game_id, language_code) DO NOTHING;
