INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('valkyrie', 94342, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mln.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw4pt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valkyrie', 'Valkyrie is, according to the box, one of the most simple to use flight simulators ever created. The game is designed to be as easy as possible to use while teaching you the basics of dogfighting at the same time. The game automatically adjusts the ship''s rotor according to your input, leaving you free to decide how to attack or evade the oncoming enemies! The game features ten different missions with varying difficulty levels and three-dimensional graphics. You can fight up to three computer opponents during your training sessions, and missions where you attack the enemy or defend your base. The game was created by one man: Donald A. Hill, Jr.' FROM games WHERE igdb_id = 94342 ON CONFLICT (game_id, language_code) DO NOTHING;
