INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armaëth: The Lost Kingdom', 'In ancient times, the dwarven kingdom Dol Armaëth was overrun by evil forces, but the wise king Armaëth managed to drive them out. Unfortunately, evil came back after Armaëth''s death and the kingdom was forgotten. The player aids the treasure hunter Killian in his search for Dol Armaëth.' FROM games WHERE igdb_id = 2311 ON CONFLICT (game_id, language_code) DO NOTHING;
