INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McDonald''s Treasure Land Adventure', 'McDonald''s Treasure Land Adventure is a side-scrolling adventure starring Ronald McDonald. After finding a piece of a treasure map, the yellow clown travels through four different levels (Forest, Town, Sea and Moon). He''s off to find and defeat the baddies who have the other pieces of the map. Ronald can jump, shoot and use his scarf to grab onto hooks to jump to higher levels. Jewels and flowers collected in each level can be used to purchase extra lives and power-ups in shops between levels.' FROM games WHERE igdb_id = 36923 ON CONFLICT (game_id, language_code) DO NOTHING;
