INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyramid Patrol', 'Pyramid Patrol is a very traditional FMV-based rail shooter. The player''s ship and small enemies are sprites, while the stages are presented using full-screen FMV stored as laserdisc video. Pyramid Intruder, the 3DO port, improves on the original game by switching from a first-person perspective to a behind-the-ship view in order to make it possible to dodge enemies; it also adds new realtime 3D levels in between the original levels.' FROM games WHERE igdb_id = 94715 ON CONFLICT (game_id, language_code) DO NOTHING;
