INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit''s Interactive Reading Journey', 'Reader Rabbit''s Interactive Reading Journey is a 1994 video game released on the Windows and Macintosh systems. It is the sixth game in the Reader Rabbit franchise. Designed for ages 4 till 7, the game introduces the new main characters Mat the Mouse and Sam the Lion who accompany Reader.' FROM games WHERE igdb_id = 355948 ON CONFLICT (game_id, language_code) DO NOTHING;
