INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Strike II', 'Power Strike II is a top-down vertical shoot ''em up video game developed by Compile. It was published by Sega in 1993, only released in Europe and Brazil. This game moves from the setting of previous games to a steampunk version of the 1930s, where the player controls the Falcon Flyer and fights against sky pirates. Not to be confused with Power Strike II / GG Aleste II for the Sega Game Gear.' FROM games WHERE igdb_id = 46337 ON CONFLICT (game_id, language_code) DO NOTHING;
