INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undercover Cops Gaiden: Hakaishin Garumaa', 'Undercover Cops: Hakaishin Garumaa), sometimes referred to with or without subtitle as Undercover Cops Gaiden, is a 1993 turn-based traditional game developed and published by Irem exclusively in Japan for the Nintendo Game Boy on December 10, 1993. It is a spin-off of Irem''s 1992 beat ''em up arcade game simply titled Undercover Cops. It is also the second-to-last game Irem released for the Game Boy, with Daiku no Gen-san - Robot Teikoku no Yabō being the last.' FROM games WHERE igdb_id = 71941 ON CONFLICT (game_id, language_code) DO NOTHING;
