INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kero-kero-keroppi-no-daibouken-2-donuts-ike-ha-oosawagi', 48350, '1993-03-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/duz03w0isvtps3clvp6a.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kero Kero Keroppi no Daibouken 2: Donuts Ike ha Oosawagi', 'Kero Kero Keroppi no Daibouken 2: Donuts Ike ha Oosawagi is a Japan-exclusive action video game video game for children that was released on the Family Computer console in 1993. This video game has Sanrio''s character searching for lost children who have been kidnapped by monsters. Essentially a standard Super Mario Bros. clone, the player controlling the cartoon frog has to leap around platforms jumping on baddies or killing them with his croak weapon. Each bonus level involves matching characters from the Sanrio franchise in a format similar to the card game Concentration. Intermission screens show the progress of the character throughout the game. Levels range from the forest to a seaside setting.' FROM games WHERE igdb_id = 48350 ON CONFLICT (game_id, language_code) DO NOTHING;
