INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-widget', 42495, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vei.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Widget', 'Super Widget is a platform game for the Super Nintendo, based on the cartoon show, Widget. It shares some similarities to the game Felix the Cat in how the main character upgrades their weapon as they collect more power-ups. Widget navigates through various worlds as he travels to Earth, picking up ''W'' coins - 100 earns him an extra life. There are also special power ups in different categories - these allow Widget to transform into a variety of different creatures, each with their own different ranged attack. As the player collects more power-ups of the same type (up to three), they change into more powerful creatures. If the player gets hit while transformed, they change back to the previous creature. If they get hit while as normal Widget, they lose a life. At the end of each world is a boss character. These are larger enemies that require learning their basic pattern, avoiding their attacks, and then firing back with your own. After defeating the boss, the player is graded based on how long it took to complete the level and their combat skills. They are then awarded ''Watcher Experience'' based on these grades.' FROM games WHERE igdb_id = 42495 ON CONFLICT (game_id, language_code) DO NOTHING;
