INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Link: The Faces of Evil', 'Link: The Faces of Evil was the product of a compromise between Nintendo and Philips following their failure to release a CD-ROM based add-on to the Super Nintendo Entertainment System. The Faces of Evil differ from most conventional Zelda games as it is a platformer with a side-scrolling view, similar to The Adventure of Link. Stages are accessed from a world map, with more becoming available as Link clears an area or defeats a boss. The game have been subject to much criticism and Nintendo does not recognize it as part of the series.' FROM games WHERE igdb_id = 8532 ON CONFLICT (game_id, language_code) DO NOTHING;
