INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Books: Little Monster at School', 'Little Monster at School is an interactive story game, based on the book by Mercer Mayer. Little Monster explains how school is fun and things to do in school, along with trying to help a monster kid named Yally get along with school. On the pages after the first part of the story is read to the player. Objects in the background may be clicked to reveal hidden surprises. While playing, click on some of background objects and find a little furry mutant.' FROM games WHERE igdb_id = 45917 ON CONFLICT (game_id, language_code) DO NOTHING;
