INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OutRun 2019', 'In the 21st century, if you''re doing 200mph, you''re holding up traffic. Welcome to Outrun 2019 - a worldwide racing tour where gutsy drivers compete over death defying tracks in a survival of the fastest.' FROM games WHERE igdb_id = 45767 ON CONFLICT (game_id, language_code) DO NOTHING;
