INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Party Quiz Mega Q', 'Party Quiz Mega Q is a 1993 quiz game for the Sega Mega Drive by Sega released exclusively in Japan. The game presents itself as a quiz show where you answer questions for points. Each of the four buttons (A, B, C, and any D-pad button) represents a choice — simply hit the button to make a choice. Get a question wrong and you lose points.' FROM games WHERE igdb_id = 45611 ON CONFLICT (game_id, language_code) DO NOTHING;
