INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolfchild', 'The world''s most renowned biogenetic scientist has been kidnapped and brainwashed into creating an army of bloodthirsty mutant warriors. Suddenly the fate of all mankind rests in the hands of his youngest son... and a top-secret mutating experiment known as "Project Wolfchild." -10 freaky levels filled with mind-blowing mazes, brain twisting puzzles and against all-odds combat action. -CD-quality graphics and a rockin'' stereo soundtrack -Grusome cast of unrelenting schitzoid mutants, each with the power to destroy -Fully animated introduction sequence' FROM games WHERE igdb_id = 4403 ON CONFLICT (game_id, language_code) DO NOTHING;
