INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sailor Moon', 'Sailor Moon (or Bishoujo Senshi Sailor Moon) is a beat ''em up video game developed by Angel in 1993, and ported to the Super Nintendo Entertainment System. It was localized in Europe exclusively in French in 1994. The Mega Drive version was developed and published by Ma-Ba, although certain elements were recycled from the Super NES version.' FROM games WHERE igdb_id = 38280 ON CONFLICT (game_id, language_code) DO NOTHING;
