INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('final-stretch', 42277, '1993-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/obthpi69divrxwbw8lkp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Stretch', 'Final Stretch is a Formula One racing game developed by Genki. It is the spiritual sequel to their earlier game Aguri Suzuki F-1 Super Driving (rebranded in the US as Redline: F1 Racer), and like that game Final Stretch is licensed by FOCA and supervised by Japanese F1 racer Aguri Suzuki. The game employs a Mode 7-enabled viewpoint close to the ground that has multiple vantage points that the player can switch between and, with the FOCA license, uses many of the then-current F1 teams and racers. Unlike Redline: F1 Racer, Final Stretch was never released outside of Japan.' FROM games WHERE igdb_id = 42277 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42277 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
