INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beavers', 12350, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8i81.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ebopqvhuhs2uoaols0ov.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beavers', 'You take the role of Jethro. The aim of the game is to make your way through each level of the game, overcoming the various Rabbits allies you will encounter. For every six levels of the game that you complete, you will be given a code so that he can continue his struggle at a later date. However, the Rabbits don''t take too kindly to this, so they send their biggest and most dangerous followers to attack you just prior to him being given the code. To defeat these large beasts, use your spin attack to propel the missiles back at them. Watch out, as rocks are too heavy to bat with your tail and you will use an energy point in trying.' FROM games WHERE igdb_id = 12350 ON CONFLICT (game_id, language_code) DO NOTHING;
