INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batsugun', 'Batsugun is a vertically scrolling shoot ''em up video game created by the now-defunct Japanese game developer Toaplan. The title translates to "exceptional" or "extraordinary". It was the final game created before Toaplan''s dissolution, and has been regarded as a key title in the development of the modern manic shooter, with elements of the game such as the size of the player''s hitbox, the scale of their firepower, and the complexity of enemy bullet patterns all having an influence on future titles in the sub-genre. Members of the development team also went on to work on other successful manic shooters, most notably lead artist Junya Inoue.' FROM games WHERE igdb_id = 16126 ON CONFLICT (game_id, language_code) DO NOTHING;
