INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-game-of-life-rpg-jinsei-game', 48819, '1993-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4w61.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Game of Life: RPG Jinsei Game', 'The Game of Life: RPG Jinsei Game is a Japan-only role playing game for the Family Computer that is similar to Jinsei Game, which is the Japanese version of The Game of Life. The object is to explore a city full of stores, places of employment, and learning places. Starting from home, the player must earn money and statistics in order to unlock the better features of the game. Unlike most games based on the Jinsei Game series, RPG Jinsei Game doesn''t use a spinner system. Instead, the controller pad is used for movement and random encounters are featured like in Dragon Quest. The player can also talk to strangers who might either give him/her advice or do something malevolent to him/her. As in the actual Game of Life board game, the player has to choose from a series of careers ranging from a musician to a photographer and even a professional wrestler. Most of these tasks are mundane while one of the quests directly involves chasing down unidentified flying objects. Buildings that are crucial to the quest (other than shops and learning places) can be fully explored; otherwise the player simply talks to the resident. Fights can occur like in a real role-playing game. However, the players stats are used instead of hit points and magic points.' FROM games WHERE igdb_id = 48819 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48819 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
