INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-jelly-bean-factory', 62672, '1993-11-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wsmuuk5ieemnanifjby9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Jelly Bean Factory', 'A DOS game where players must clear the board by aligning jelly beans.  Coloured blocks, or jelly beans fall from the top of the screen. Each bean has three coloured balls in it and the player must position them so that when they hit the bottom of the screen they make rows of three or more of the same colour. The colour sequence of each bean can be altered as it falls, there are reject beans that are hard to remove and there are clearing beans that remove all beans that match the first colour they make contact with.  The game is controlled either by the keyboard or by a keyboard/joystick combination. It has optional sound, a high score table, four levels of difficulty, nine levels, and other customizable options.' FROM games WHERE igdb_id = 62672 ON CONFLICT (game_id, language_code) DO NOTHING;
