INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hired Guns', 'Hired Guns takes the player to the far reaches of the Luyten planetary system. Battling through over 20 theaters of engagement, collecting weapons, scanners and food, your team of mercenaries test the limits of their military prowess in this high-tech battle adventure game. The game features a split-screen multiplayer mode for up to four gamers, plus utilizes a unique custom digital terrain processor built for the game for realistic 3D views.' FROM games WHERE igdb_id = 2527 ON CONFLICT (game_id, language_code) DO NOTHING;
