INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Patrol 2: Drug Wars', 'Crime Patrol 2: Drug Wars (also known just as Drug Wars) is a live-action laserdisc video game, released by American Laser Games in 1993. It was subsequently ported to the 3DO Interactive Multiplayer and CD-i. As the title implies, it is the sequel to the relatively popular arcade game Crime Patrol, with very similar gameplay, objectives and scenery. The game was re-released by Digital Leisure in 2002.' FROM games WHERE igdb_id = 4242 ON CONFLICT (game_id, language_code) DO NOTHING;
