INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ranger X', 'Engage in airborne combat with jump-jets and weapons of incredible power or link up with your cyber cycle for high speed ground attacks. Each step inches you closer to your goal and the fight of your life. You are Ranger X... A mysterious lone warrior who has risen from the ashes to return peace and justice to a failed society. Eight post-apocalyptic levels of high-intensity action! Monstrous mechanical bosses await your every move. Use jump-jets to attack by air or transform into the Super Cyber Cycle and roll to victory!' FROM games WHERE igdb_id = 46265 ON CONFLICT (game_id, language_code) DO NOTHING;
