INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mountain-bike-rally', 42485, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z3g.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mountain Bike Rally', 'The player starts in qualifying, and as he/she plays the game more frequently, he/she can qualify for the regionals, nationals, the championship, and the grueling final race where he/she must get first place in order to beat the game. Players will spend literally hours in the easier modes and this game is like exercise for his/her thumbs.' FROM games WHERE igdb_id = 42485 ON CONFLICT (game_id, language_code) DO NOTHING;
