INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('graham-gooch-world-class-cricket', 14248, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kmtlzlubybahe4xyblql.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Graham Gooch World Class Cricket', 'One of the few computer games recreating cricket, the traditional summer pastime in many English-speaking countries. The game had different licenses with well-known cricketers in different countries. It was Audiogenic''s second cricket game, 8 years after Graham Gooch''s Test Match. All the international sides are present, with the chance to change the player data and choose the team yourself. Test match and limited-overs matches are available, with 1 or 2 innings per team, and you can turn the Leg-before-wicket dismissal off, which makes the game easier to understand. There are 3 skill levels - Amateur, Professional and World Class. The bowling involves positioning a cursor to place the bowl, then controlling the speed/spin (depending on the type of bowler selected). Batting involves timing one of the many available shots, and fielding is largely automated.' FROM games WHERE igdb_id = 14248 ON CONFLICT (game_id, language_code) DO NOTHING;
