INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eight Ball Deluxe', 'Eight Ball Deluxe is a digital pinball game, adapted from a physical pinball machine manufactured by Bally in 1981. The digital game was mad by Japanese developer LittleWing and released in 1993. The game is themed around cowboys playing billiards.' FROM games WHERE igdb_id = 67511 ON CONFLICT (game_id, language_code) DO NOTHING;
