INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tengen-world-cup-soccer', 46329, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yqj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc69iv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tengen World Cup Soccer', 'The game has an unusual naming scheme. In Japan there were no issues, as the game was published by SIMS themselves. In North America and PAL regions however, publishing rights were given to Tengen, who altered many of the in-game banners and renamed the game Tengen World Cup Soccer, even though the majority of the work was done by SIMS. The game offers 24 different national teams from across the world, although the choices aren''t based on any official tournament from the era. For 1993 the list is quite out of date; the Federal Republic of Germany (more commonly known as West Germany) had not existed since 1990 after the fall of the Berlin Wall, Russia is represented with the flag of the Soviet Union which dissolved in late 1991, and Yugoslavia had ceased to exist by mid-1992.' FROM games WHERE igdb_id = 46329 ON CONFLICT (game_id, language_code) DO NOTHING;
