INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taz-Mania', 'This version of Taz-Mania is different from the side-scrolling versions by Sega, in this version the player controls Taz from a third-person perspective. The goal of the game is to travel down the road, collecting Kiwi''s before the timer runs out, avoiding obstacles along the way. The Kiwi''s will get harder to catch as the game goes on, jumping over Taz and actually outrunning him at times.' FROM games WHERE igdb_id = 158990 ON CONFLICT (game_id, language_code) DO NOTHING;
