INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rokudenashi-blues', 48820, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co54zj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciirj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rokudenashi Blues', 'An RPG brawler released for the Family Computer and Super Famicom based on the anime and manga of the same name. Both were developed by TOSE and published by Bandai. Rokudenashi Blues ("Good-for-Nothing Blues") is a RPG brawler based on the manga of the same name, which also saw two anime movie adaptations close to its release. The player character, Taison Maeda, is a delinquent student who is training to be a professional boxer. He has a reputation as a powerful fighter among delinquent gangs as a result, though despite being violent he has a code of honor. The Famicom and Super Famicom versions of the game are subtly different due to console differences, but both share their genre, developer and publisher. The Famicom game was released in October 1993, with the Super Famicom version following in April 1994. Characters from this game have appeared in Jump crossover games, specifically Famicom Jump II and Jump Ultimate Stars.' FROM games WHERE igdb_id = 48820 ON CONFLICT (game_id, language_code) DO NOTHING;
