INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mansion of Hidden Souls', 'Mansion of Hidden Souls is an adventure game created entirely with full-motion video. It takes place in a pre-rendered mansion that the player explores from a first-person perspective. As they wander from room to room, the action unfolds via video sequences. The player takes on the role of Jonathan, a boy whose sister has wandered into the spooky mansion. When she entered the mansion, she disappeared! What''s more, the mansion is full of talking butterflies. The player must search the whole mansion to unlock its secrets and find Jonathan''s sister.' FROM games WHERE igdb_id = 5402 ON CONFLICT (game_id, language_code) DO NOTHING;
