INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman Returns', 'The SNES version of the game was released in 1993. It is fundamentally a left-to-right scrolling fighter beat ''em up, a genre that was featured heavily on the console at the time. The gameplay and graphics are very similar to the Final Fight games. The game takes the player through seven scenes featured in the film. Each scene has a boss fight that Batman must win in order to proceed to the next scene.' FROM games WHERE igdb_id = 121242 ON CONFLICT (game_id, language_code) DO NOTHING;
