INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ridge Racer', 'Ridge Racer was initially released on the Namco System 22 arcade system board and was later ported to the PlayStation console. It is the first title in the long-running Ridge Racer series of games released for arcades and home consoles. The game''s objective is to finish in first place in a series of races. Ridge Racer was among the first racing games to utilise polygon graphics to its full potential.' FROM games WHERE igdb_id = 18696 ON CONFLICT (game_id, language_code) DO NOTHING;
