INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-invaders-dx', 39409, '1993-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fn8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc897r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Invaders DX', 'A remake of the original with several new options and gameplay elements, including a competitive two-player mode. Introduced a "parody mode" that replaces the traditional sprites by those from other Taito games including Arkanoid, Bubble Bobble, The NewZealand Story, and Darius. Early versions use Taito''s B system hardware, while later ones use Taito''s F3 system hardware. The home versions were released as Space Invaders - The Original Game. Other names include: Space Invaders XL on the Nuon, Space Invaders ''​94 on the Game Boy and Super Nintendo Entertainment System, and Space Invaders 2000 and Space Invaders 1500 on two PlayStation re-releases. The home releases feature variants of the two-player mode. The Game Boy release was an update to the 1990 version of Space Invaders Part II. Extra options similar to Space Invaders DX are available when played via Nintendo''s Super Game Boy. The first PlayStation release lacked the two-player mode. Subsequent PlayStation re-releases in 1998 and 2001 restored it. The 2001 release, known as The Invaders and Space Invaders 1500, includes a 3D version, and was part of D3 Publisher''s Simple series of budget games that sell for ¥1500. The Super Nintendo Entertainment System version was also released on Nintendo''s Virtual Console.' FROM games WHERE igdb_id = 39409 ON CONFLICT (game_id, language_code) DO NOTHING;
