INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Instinct', 'The original Arcade version of Power Instinct. This version only has the arcade mode and multiplayer while the later ports to console added practice, battle, time attack and life attack game modes. Power Instinct is a one-on-one 2D fighting game in the tradition of Street Fighter 2, in which you select your character from a group of 8 unique fighters and attempt to defeat your opponents in successive fashion using your arcade reflexes and your character''s unique moves.' FROM games WHERE igdb_id = 4476 ON CONFLICT (game_id, language_code) DO NOTHING;
