INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nostradamus', 40257, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/i0yyg4qyhd12um1nentr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nostradamus', 'Nostradamus is a vertically scrolling arcade shoot ''em up released by Face in 1993.  Players control either Dalas (player one) or Joanna (player two) to shoot down many different enemies and then defeat the level boss to advance through the game''s nine stages.  According to one of Nostradamus'' supposed prophecies, in July 1999, a great leader would come from the sky to rebirth an old ruler over a lost province on Earth. In the game''s story, this prediction comes true in the form of an alien invasion. Originating from Saturn, the alien invasion force quickly attacks many locations on Earth in preparation for an even bigger assault and possible complete global domination. Efforts are put into the design of advanced space fighters and mecha along with the best fighter pilots - in this case, pilots Dalas and Joanna - to combat the Saturnites and dispel any further doom prophecies from materializing on Earth.' FROM games WHERE igdb_id = 40257 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40257 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 40257 AND p.igdb_id = 52 ON CONFLICT DO NOTHING;
