INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sangokushi-iii', 350289, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobu5j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5m0z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sangokushi III', 'The PC-Engine CD-ROM version of Sangokushi III (Romance of the Three Kingdoms III) includes an additional scenario: The Yellow Turban Rebellion (AD 184) After choosing the scenario, players determine which warlord(s) they will control. Custom characters may be inserted into territories unoccupied by other forces. A total of 46 different cities exist, as well as hundreds of unique characters. Each character has several statistics: War Ability, Intelligence, Politics, Charisma, Army Command, Naval Command. The player wins the game by conquering all territories in China. This is accomplished by being in control of every city on the map.' FROM games WHERE igdb_id = 350289 ON CONFLICT (game_id, language_code) DO NOTHING;
