INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kamen-rider-sd-shutsugeki-rider-machine', 38166, '1993-07-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4d3h.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider SD: Shutsugeki!! Rider Machine', 'Kamen Rider SD: Shutsugeki!! Rider Machine ("Masked Rider SD: Roll Out!! Rider Machine") is a racing game that takes the characters from the Kamen Rider tokusatsu TV show and manga and puts them in a much cartoonier, super deformed universe. The game scrolls horizontally like a brawler, but the player (as Kamen Rider) is always in motion on a motorcycle and must destroy the bikes and vehicles of his enemies by kicking and punching to his sides, similar to Road Rash. Yutaka put out three Kamen Rider SD games for Nintendo consoles in 1993, and this SNES game is the middle child of this trio. The other two are Kamen Rider SD: GranShocker no Yabou for the NES and Kamen Rider SD: Hashire! Mighty Riders for the Game Boy.' FROM games WHERE igdb_id = 38166 ON CONFLICT (game_id, language_code) DO NOTHING;
