INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ww2-air-force-commander', 2396, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lu9dwdqb1sjm5dnfebyu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WW2 Air Force Commander', 'Take command of the airforce in this exciting and challenging simulation of air warfare in the Second World War! As commander, you''ll have complete control over your side''s entire air force, and must plan how to use them to best effect. Decide where to locate each unit, and set up appropriate missions for each one. You''ll need to set up defensive patrols to secure the safety of your key sites as well as offensive missions to take out the enemy''s strike capability! The Battle of Britain early, in World War II was the first large-scale air war. Continental Europe had fallen to the Nazi Blitzkrieg attacks, and Britain alone remained free and fighting. Without the years of preparation the Germans had, the Royal Air Force had many fewer planes than the Luftwaffe; the outlook was bleak. But with heroic bravery and careful planning, the Spitfires and Hurricanes managed to stave off German bombers for long enough for Britain to survive, and America to join in the fight against tyranny. Now you can recreate this and many other scenarios. The Battle of Britain showed just how important it is to be master of the skies- are you up to the job? Air Force Commander: World War Two Edition, is the second game in the Air Force Commander series, and follows the success of the first game, set in the Middle East.' FROM games WHERE igdb_id = 2396 ON CONFLICT (game_id, language_code) DO NOTHING;
