INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Z-senshi Daishugyou!', 'A Dragon Ball Z LCD Game. This is a fighting game which features the Z Fighters in their Cell Games Saga appearance. The player controls Super Saiyan Gohan and fights against Trunks (Base and Super Saiyan), Vegeta (Base and Super Saiyan), Piccolo and Krillin. This game also features a voice for Gohan when he attacks. It also features the voice of Goku (Masako Nozawa) when the player clears a stage.' FROM games WHERE igdb_id = 346787 ON CONFLICT (game_id, language_code) DO NOTHING;
