INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-ren-and-stimpy-show-veediots', 7989, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2doj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ren & Stimpy Show: Veediots!', 'Veediots! lets the player experience four classic episodes of the Ren & Stimpy Show. One is the episode, "The Boy Who Cried Rat", where the player takes control of Ren, who''s dressed like a mouse, in which he has to reach the end of a house while avoiding obstacles and enemies as well as Stimpy. Towards the end of this stage, the player must travel through Stimpy''s mouth in order to complete the stage by avoiding various pitfalls and obstacles. The second episode is "In the Army" where once again the player takes control of Ren as they travel through an army base, punch at enemies including soldiers, avoid various pitfalls and use various objects scattered throughout the stage in order to advance. The third episode is "Stimpy''s Invention", where the player takes control of Stimpy as they must escape a demented laboratory by avoid pitfalls and enemies and collect items to complete the "Happy Helmet" and use it on Ren in order to complete the stage. The final stage is "Marooned" where the player takes control of Stimpy and is swallowed by a giant alien and must avoid various enemies as the fall down the throat of the giant alien. Once Stimpy lands in the stomach, the player must make it to the end of the level, attacking enemies and avoid pits of acid in order to reach the end of the stage. There are also power-ups for each stage including health icons and powered toast icons that will give the player a brief stint of invincibility. The game also features the voice talent of Billy West.' FROM games WHERE igdb_id = 7989 ON CONFLICT (game_id, language_code) DO NOTHING;
