INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heberekes-popoon', 42610, '1993-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w1j.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hebereke''s Popoon', 'Hebereke''s Popoon is a block-grouping game closer in style to Dr. Mario than Tetris. There are eight playable characters, each having different abilities. In one-player mode, the player is forced to choose Hebereke and must play against Oh-Chan. After defeating Oh-Chan, the player is allowed to choose between Hebereke and Oh-Chan in the next match against Sukezaemon, and so on, until the player has "unlocked" all the characters. Each match consists of a single-round. A defeated player may elect to resume play by using a continue. In two-player mode, all characters are immediately available to either player and each match is the best of three rounds. Players can also select a handicap level (from 1 - 5) to increase or decrease the difficulty of the game.' FROM games WHERE igdb_id = 42610 ON CONFLICT (game_id, language_code) DO NOTHING;
