INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen-Nippon Pro Wrestling', 'Step into the ring! Choose from 16 of All Japan Pro Wrestling''s wrestlers and bring it on! Wield the massive power of Hansen, the lightning-fast strikes of Kawada, the underhanded attacks of ACE, and many more mad men of the ring! With its robust grappling system and over 50 moves to master, All Japan Pro Wrestling delivers the deepest and most realistic wrestling action of the 16-bit era! Test your might against the crafty AI, or up to 4 players can compete in exhibition, tag team, and round robin matches!' FROM games WHERE igdb_id = 61503 ON CONFLICT (game_id, language_code) DO NOTHING;
