INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-rush-build-up-robot-tournament', 48520, '1993-11-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vlux3kieevs6eods9e5p.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Rush: Build Up Robot Tournament', 'The player has to build his own combat robot to use in a fighting tournament. These robots are built in factories that assign the robot a name in addition to installing its head, body, shoulder, and feet. The player has a pre-game lobby to get ready for the robot combat action. All matches have rounds of 60 seconds (unlike the 99-second round of most modern fighting video games). Both robots have a separate gauge for energy and damage. Standard punches and kicks can be thrown in addition to special moves (which look like ammunition).' FROM games WHERE igdb_id = 48520 ON CONFLICT (game_id, language_code) DO NOTHING;
