INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cannon-fodder', 5519, '1993-01-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3o3f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zjh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannon Fodder', 'Cannon Fodder is an action-strategy shoot ''em up game developed by Sensible Software and published by Virgin Interactive. The game is military-themed and based on shooting action but with a strategy game-style control system. The player directs troops through numerous missions, battling enemy infantry, vehicles and installations. Cannon Fodder has a darkly humorous tone which commentators variously praised and condemned. Its creators intended it to convey an anti-war message, which some reviewers recognised, but the Daily Star and a number of public figures derided the game. In other respects, reviewers highly praised the game, which widely achieved scores of over 90% in Amiga magazines. Amiga Action awarded it an unprecedented score, calling it the best game of the year.' FROM games WHERE igdb_id = 5519 ON CONFLICT (game_id, language_code) DO NOTHING;
