INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('night-walker-mayonaka-no-tantei', 111999, '1993-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6q02.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn9aj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Walker: Mayonaka no Tantei', 'a 16-color PC-9801 eroge released by Tomboy in December 1993. Nightwalker is an adventure game, focused mostly on character interaction and problem solving. While the main characters of this game have the same names and similar appearances to their anime equivalents, their personalities are generally more easy-going and their backgrounds are less tragic (they all have living relatives). In comparison to the anime, the game is fairly lighthearted, with Shidō and Guni providing comic relief. Nightwalker was initially developed as a spin-off project of the adult game Bishōjo Audition: Find an Idol released by Tomboy in February 1993, with the character Rihoko Ayukawa from that game reappearing as a heroine. However, in the process of refining the setting, the heroine''s name was changed to Riho Yamazaki, her design was changed, and the story and setting were separated from the previous work. The concept of the world of Nightwalker itself is based on illustrations from 1992.' FROM games WHERE igdb_id = 111999 ON CONFLICT (game_id, language_code) DO NOTHING;
