INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marios-time-machine', 48133, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wwm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2e25.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Time Machine', 'Mario''s Time Machine is an edutainment title and the successor of Mario is Missing! The game is meant to teach younger players basic world history and is the last Mario Discovery Series game before discontinuation. This game and Hotel Mario are the only games in the Mario franchise in which Mario as a protagonist has full lines of dialogue. The objective of the game is to return the historical artifacts to their proper time periods thanks to the central hub. As soon as you enter a certain time period you need to explore and interact with various residents of the area in order to get more information about the artifact, the period itself and the person connected to it.' FROM games WHERE igdb_id = 48133 ON CONFLICT (game_id, language_code) DO NOTHING;
