INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock n'' Roll Racing', 'The game pits four racers against each other, with up to two of them being player-controlled and the rest being AI opponents. Each race consists of four laps around tracks viewed from an isometric perspective, which enables players to discern the presence of frequent sloping sections spread throughout the game''s various tracks. In addition to navigating the turns, racers must also maneuver hills and dips without falling or jumping over the guard rail at the track''s edge.' FROM games WHERE igdb_id = 6564 ON CONFLICT (game_id, language_code) DO NOTHING;
