INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('viper-v6', 305254, '1993-06-25', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scsoz7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viper-V6', 'Viper V-6 is the first in the long-running Viper series of animated adult games. It contains three separate stories:The Devil Came* tells the story of a teenager named Ogawa, who was unpopular in his class and summoned a demon to exact revenge. But the demon turned out to be female, so his wishes naturally assume a different direction... Afternoon describes a scene during a beauty contest. The defeated participant thinks that she was unfairly judged, but her fury at the winner turns, in front of the amazed spectators, into erotic desire... Double Impact features two young female detectives, Miho and Kumi, who pretend to search for jobs as maids in order to infiltrate a mansion in which mysterious disappearances have been taking place. All the three stories are very short and can perhaps be better described as "scenes"; the entire game can be completed within several minutes. The interaction is reduced to absolute minimum, with an occasion decision to make, and is available only in The Devil Came (in which it is also possible to die if the player makes a wrong decision); the two other stories are non-interactive, the only input being pressing the return key to advance to the next scene. What sets "Viper V-6" (and the whole series) apart from most other Japanese adult games - beside the "three stories in one" concept - is the fact that most of its sex scenes are animated.' FROM games WHERE igdb_id = 305254 ON CONFLICT (game_id, language_code) DO NOTHING;
