INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Toon Adventures 2: Montana''s Movie Madness', 'Here comes Montana Max the meanest movie maker to ever tarnish the silver screen. He''s directed four new flicks that make Buster Bunny look like a villain! To defend his character Buster Bunny must leap into Max''s movies and use attack moves like fast dash and freeze kick to change the endings before his career is finished.' FROM games WHERE igdb_id = 8048 ON CONFLICT (game_id, language_code) DO NOTHING;
