INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sumo Fighter', 'Appetite For Adventure Shape up your Nintendo GAME BOY with foot-stomping action. Eat your way to super strength and pound everything in your path. Pick on everyone lighter than you as you make your way through 15 enemy-filled stages. Find the secret temples and take on the bonus stage challenges of thumb wrestling, arm wrestling or tradtional sumo fighting. Remember, don''t forget to eat your rice!' FROM games WHERE igdb_id = 49006 ON CONFLICT (game_id, language_code) DO NOTHING;
