INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangerous Dave''s Risky Rescue', 'Unfortunately for our hero, his little brother is afflicted with “always getting kidnapped” syndrome. Dangerous Dave must battle wolves, mummies, ghosts, and other ghastly apparitions on his way to save Delbert from the clutches of the evil Dr. Nemesis. With 11 levels of spine-tingling platforming action, you’ll be shooting up a storm in Dangerous Dave’s Risky Rescue!' FROM games WHERE igdb_id = 11388 ON CONFLICT (game_id, language_code) DO NOTHING;
