INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-combat-falcons-revenge', 44461, '1993-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5mte.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1xds.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Combat: Falcon''s Revenge', 'Following the events of Battle Clash, the Battle Game Chiefs had been defeated. But the world did not return to peace and instead new Chiefs and new machines rose up to rule the world. Like before, the Chiefs use giant robots known as Standing Tanks (STs). Seeing the world in trouble, the hero pilots who had defeated the Battle Chiefs decide to once again enter the Battle Game using an improved version of their ST, the Falcon. The truth behind the Battle Game will take the Falcon deep into space... Metal Combat: Falcon''s Revenge is a first person shooter designed for the Super Scope Light Gun. Gameplay is identical to Battle Clash. The player takes the role of the gunner of the giant robot, movement is handled automatically by the game, scrolling the screen. Players must keep the enemy robot in the gunsights and blast away at different parts of it, while also intercepting enemy missiles and counter-attacks. All robots have a weak point that will increase the damage done to them. Power-ups such as Neutron Beams and Plasma Bombs can be picked up following the completion of certain stages, and equipped at the beginning of combat.' FROM games WHERE igdb_id = 44461 ON CONFLICT (game_id, language_code) DO NOTHING;
