INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kunio''s Dodgeball Time, C''mon Guys!', 'Okay, listen up! Nekketsu High Dodgeball Club has proven themselves once before on the world arena, but now, the stakes are higher! We got to go out there again and show why Nekketsu High is the greatest team in the world. Lead us to victory, Kunio! Kunio-Kun no Dodge Ball Dayo Zennin Shuugo! is the Super Famicom sequel to the original Dodgeball for the Famicom, "Nekketsu Koukou Dodgeball-bu".' FROM games WHERE igdb_id = 42516 ON CONFLICT (game_id, language_code) DO NOTHING;
