INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SWmud', 'Star Wars MUD, or SWmud, is a telnet text-based game set in the Star Wars universe, mostly during A New Hope to the Thrawn (Legends) campaign. Player killing is optional. Great space combat and newbie help! Star Wars mud is a heavily modified LPmud based on the Star Wars Universe. SWmud is not a role-playing MUD, though role-playing is not forbidden as long as it is within the rules.' FROM games WHERE igdb_id = 228912 ON CONFLICT (game_id, language_code) DO NOTHING;
