INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Los Justicieros (Zorton Brothers)', 'Los Justicieros is a video game created by Dinamic Multimedia in 1996 as a version of the recreational game Los Hermanos Zorton . It is the first, and so far only (apart from the game Corruption in Marbella , which was only distributed in recreational) Spanish interactive film . It was produced by PicMatic SA and Snatcho .  The game was a revolution at the time to be entirely composed of real scenes shot in the desert of Almeria and directed by the director Enrique Urbizu . It counted on specialists of cinema in charge of the falls, persecutions and explosions.' FROM games WHERE igdb_id = 119398 ON CONFLICT (game_id, language_code) DO NOTHING;
