INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akumajyo Dracula Peke', 'Akumajyo Dracula Peke is a hidden minigame that came included with Castlevania: Rondo of Blood. It is also known as Stage X "The Fate of Blood Must be Cut with the SUPER CD-ROM² ROM" (血の因縁はSUPER CD・ROM²でなければ断てない, Chi no Innen ha Super CD-ROM² ROM de Nakereba Tatenai). This minigame played instead of Rondo of Blood if the user was using the wrong kind of System Card. The game has been included in all conversions of Rondo of Blood, only differing on the methods of unlocking it between platforms.' FROM games WHERE igdb_id = 266915 ON CONFLICT (game_id, language_code) DO NOTHING;
