INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-godzilla', 38418, '1993-12-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8r83.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar33ka.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Godzilla', 'Super Godzilla is a 16-bit Godzilla game where the player can take control of Toho''s famous big green lizard as they rampage through Japan. The game is divided into two main gameplay modes, Movement and Battle. Movement has the player travel through the city using the D-pad and a map located on the bottom of the screen with the objective being to destroy certain objectives such as enemy humans and buildings as well as pick up power-ups. There is an animation in the screen above the map that shows the results of their movements and attacks. Battle mode kicks in when the player locates an enemy on the map, like Biollante or Mechagodzilla, and is taken to a side-scrolling cinematic-style battle where the player must use punches, tail whips and the famous fire breath to drain the energy of the opposing monster. However, the Fighting Spirit system is present which is in a sense a morality meter where the player must pick the right attacks at the right time in order to connect certain attacks. Choosing the wrong attacks or failing to connect with them will cause the meter to drop and make Godzilla more vulnerable to attack.' FROM games WHERE igdb_id = 38418 ON CONFLICT (game_id, language_code) DO NOTHING;
