INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crayon-shin-chan-ora-to-shiro-ha-otomodachi-da-yo', 49131, '1993-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pfd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdsu9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayon Shin-Chan Ora to Shiro ha Otomodachi Da yo', 'Crayon Shin-Chan: Ora to Shiro ha Otomodachi Dayo is a platforming game based off the Crayon Shin-Chan manga, mostly popular in Japan although translated and published in a couple of other countries. The game is heavily oriented towards platforming, with only a couple of blow bubbles-based weapons littered throughout the game''s short four levels. Shin-chan can hop onto the heads of the enemy humans that are interspersed around each stage, as well as use the bubbles to knock them out. He can also hop onto hooks and branches, and scale telephone poles and trees. There are also three mini-games in Crayon Shin-Chan along with a fourth kind-of mini-game. Although all four mini-games are encountered in the course of your playthrough, you can also access them from the title screen using the second option presented to you. Also of note is a timer in each of the level. For some weird reason, if you try to collect everything in a level, there simply is not enough time, at least in Level 2. Fortunately, you are given checkpoints throughout each of the levels. Timing out will simply throw you back to one of the checkpoints.' FROM games WHERE igdb_id = 49131 ON CONFLICT (game_id, language_code) DO NOTHING;
