INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby''s Pinball Land', 'Choose your world and take aim! Kirby will be launched into the fast-paced danger of uncharted worlds, but you can help him face his foes head on. It''s a pinball race to check out each new world''s surprise enemies and pitfalls. Flip Kirby in battles against lethal eyeballs, a shooting tree and mace-swinging maniacs. Take aim and leap to new worlds!' FROM games WHERE igdb_id = 3715 ON CONFLICT (game_id, language_code) DO NOTHING;
