INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexxagon', 'A two-player board game played on a hexagonal grid. Each player starts with three pawns. Players take turns moving pawns either by cloning them to an adjacent hex or jumping them to a space two hexes away. Whenever a pawn is moved, it changes all adjacent opposing pawns to its own color. The goal to either eliminate all of the opponent''s pawns or to have more pawns when the board is filled.' FROM games WHERE igdb_id = 14479 ON CONFLICT (game_id, language_code) DO NOTHING;
