INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ihatovo Monogatari', 'The story depicts the action as taking place in the utopian world of Ihatovo. The game focuses on collecting information (notebooks from Miyazawa''s fairy tales) and items (that are related to those fairy tales) instead of fighting monsters. Some of the surprises that the player finds includes a movie theater that is always closed, the opportunity to play the role of a temporary school teacher, and having portraits of unique non-player characters that show up while talking to them. Inspired by the stories of Kenji Miyazawa, the story covers nine chapters and surreal environments.' FROM games WHERE igdb_id = 42289 ON CONFLICT (game_id, language_code) DO NOTHING;
