INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Terminator', 'Similar to adaptations of The Terminator on other systems, the Sega CD game is a platformer where the player controls Kyle Reese, who travels back in time from the year 2029 to protect Sarah Connor from the unstoppable killing machine known as the Terminator. The game consists of 10 levels. Future locations include the post-apocalyptic wasteland of 2029 Los Angeles and the time displacement complex. In the present of 1984, Reese must traverse the streets and rooftops of L.A., as well as the Tech Noir club, the police station, and, for the finale, an automated factory.' FROM games WHERE igdb_id = 234211 ON CONFLICT (game_id, language_code) DO NOTHING;
