INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thomas the Tank Engine & Friends', 'Thomas the Tank Engine & Friends is a game starring the characters from the children''s television show Thomas the Tank Engine & Friends. The game, aimed towards the preschool demographic, has players controlling several different characters from the show''s universe, including Thomas, James, Percy, Toby and Duck. Edward, Henry and Gordon also appear in the game mode with Thomas and James. The original Thomas title music is played at the title screen. This game features music from the first three seasons, and all text is spoken by Craig Ewert.' FROM games WHERE igdb_id = 128845 ON CONFLICT (game_id, language_code) DO NOTHING;
