INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry Gaiden II: Curse of the Ancient Emperor', 'Wizardry Gaiden II: Curse of the Ancient Emperor, published in 1992 by ASCII, was the second of the trilogy of Wizardry roleplaying games released for the original gray-scale Nintendo Game Boy portable video game system. .' FROM games WHERE igdb_id = 49092 ON CONFLICT (game_id, language_code) DO NOTHING;
