INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soldiers of Fortune', 'Soldiers of Fortune (Chaos Engine in the EU) is a run-and-gun overhead shooter. Sixteen levels (in four groups of four) await the players in the game. The basic gameplay is in an open air setting, with bridges across rivers and other features in the maps. The visuals are in a ''metallic and blue'' style. There are six characters available in the game, each with different strengths and weaknesses, and different starting prices.' FROM games WHERE igdb_id = 4527 ON CONFLICT (game_id, language_code) DO NOTHING;
