INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kawasaki-caribbean-challenge', 42508, '1993-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/uz9ruhbae7w40yvgdzzl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawasaki Caribbean Challenge', 'Race a Kawasaki Ninja Motorcycle or Jet Ski over 3 different islands in the Caribbean. When you''re ready, take the Challenge to see how good you really are! Look down at your vehicle from a bird''s eye view and cross bridges, make sharp turns, knock other opponent''s off the road (or ocean) and get first place, if you can! You get to choose from a selection of 3 Motorcycles and 3 Jet Ski''s when you race. You must complete 5 laps on each level and try to get first place!' FROM games WHERE igdb_id = 42508 ON CONFLICT (game_id, language_code) DO NOTHING;
