INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blades of Vengeance', 'Blades of Vengeance is a platform game that was developed by Beam Software and published by Electronic Arts for the Sega Mega Drive/Genesis. In this game, one or two players can select one of three fantasy warriors to fight through a large range of platform levels in order to defeat the forces of darkness.' FROM games WHERE igdb_id = 45565 ON CONFLICT (game_id, language_code) DO NOTHING;
