INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NetWars', 'Netwars is a classic, simple, and enjoyable 3D space shooter for up to 4 players over an IPX network. The game is also playable in a single-player mode with max of 12 computer enemies. The game is very simple and arcade based, pick-up various power-ups to increase your survival chance.' FROM games WHERE igdb_id = 14505 ON CONFLICT (game_id, language_code) DO NOTHING;
