INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla: Battle Legends', 'Godzilla: Battle Legends (simply referred to as "Godzilla" in North America) is a fighting game based on the Godzilla film franchise, made for the Turbo Duo in 1993, developed by Alfa System and published in the United States by Hudson Soft. When Godzilla fights a certain foe, his appearance changes to reflect the era when he battled in certain films. For example, Godzilla looks like as he did in 1955 when he fights Anguirus, and as in 1964 when he fights Rodan. This game''s sequel, Godzilla: Monster War for the SNES, features fewer monsters, with the inclusion of Biollante as a playable character and Mothra. In single player mode, only Godzilla is playable.' FROM games WHERE igdb_id = 72828 ON CONFLICT (game_id, language_code) DO NOTHING;
