INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Revenge', 'Dragon''s Revenge is a sequel to Dragon''s Fury (Devil''s Crush MD). The table for this fantasy pinball game is three screens tall with medieval and dragon graphics. Each of the three screens has a pair of flippers at the bottom and the table elements are all animated and numerous monsters roam the screen. The object is to hit wandering monsters and certain groups of creatures to open up the gateway to a sub-level. The single screen sub levels offer multi-ball play and are the key to scoring high.' FROM games WHERE igdb_id = 46219 ON CONFLICT (game_id, language_code) DO NOTHING;
