INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Ace', 'Sengoku Ace, fully titled Sengoku Ace: Tengai Episode I and also known as Samurai Aces in the English version, is a vertically-scrolling shoot ''em up video game originally released in the arcades by Psikyo in 1993. The first game by Psikyo, Sengoku Ace was designed by Shin Nakamura, the creator of Aero Fighters (Sonic Wings) and the company''s founder. The game features 21 endings, different for various characters and 2-player pairings.' FROM games WHERE igdb_id = 40017 ON CONFLICT (game_id, language_code) DO NOTHING;
