INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Companions of Xanth', 'Companions of Xanth is an adventure game published in 1993 by Legend Entertainment. The game is based on Piers Anthony''s Xanth novels and loosely follows the plot of his novel Demons Don''t Dream, in which a young man uses a computer game to enter and explore the world of Xanth. Typical of Piers Anthony''s novels, the game is filled with puns and visual gags, and some knowledge of the Xanth universe is helpful; for those players who haven''t read any of the Xanth novels, an in-game ''Com-Pendium of Xanth'' is provided to the player for the majority of the game.' FROM games WHERE igdb_id = 12412 ON CONFLICT (game_id, language_code) DO NOTHING;
