INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Pinball', 'Virtual Pinball is the spiritual successor to Bill Budge''s classic Pinball Construction Set. Players can choose from either 29 pre-made games or design one using the in-game editor tools. Designing options include ten different backgrounds and six themes. You also get to choose where objects are placed, the style of music, and the ball speed. Up to ten personal games can be saved.' FROM games WHERE igdb_id = 4458 ON CONFLICT (game_id, language_code) DO NOTHING;
