INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshi''s Safari', 'Yoshi''s Safari is the first and so far the only dedicated rail shooting game in the Mario franchise, and one of the few games to use the SNES''s Super Scope light gun peripheral. Gameplay consists of shooting enemies before they attack. There are bosses along the way that must be destroyed before players can move on to the next area.' FROM games WHERE igdb_id = 11604 ON CONFLICT (game_id, language_code) DO NOTHING;
