INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-chessmaster-4000-turbo', 15878, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/plbbcl4hjuxodayuqa5s.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chessmaster 4000 Turbo', 'The first 32-bit title in the Chessmaster series, Chessmaster 4000 Turbo offers features designed around the processors of the time. Modem and LAN play is available for the first time. Boards are viewed in 2D or 3D, and include many custom sets, with game options selected from surrounding windows and drop-down menus. Entering moves is now easier - if you click on a square which only one of your pieces can move to, it will move there automatically. Full games (including 500 recreated real-life classics) can be analysed from an expert perspective, and a library of common opening move sequences is included. Computer players act in a variety of ability levels and play styles - some are prepared to play for a draw, others are focused on keeping the centre of the board tidy, and so on.' FROM games WHERE igdb_id = 15878 ON CONFLICT (game_id, language_code) DO NOTHING;
