INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gensou-tairiku-aurelia', 79293, '1993-02-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6i6a.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gensou Tairiku Aurelia', 'You start the game as a nameless warrior (you can name the hero as you like). He returns to his home village, only to find it burnt down, and his beloved woman dead. Kneeling at her grave, the warrior swears revenge, but this quest soon turns out to go far beyond it, as demonic forces are threatening the land! Gensō Tairiku Aurelia is a side-scrolling action RPG. You control the warrior (and other characters whom you can control later in the game) by moving him through platform locations - towns, forests, dungeons, etc. In towns you can talk to people to advance the plot. In wilderness areas, you fight enemies by attacking physically or using magic spells in real time. You can also jump in this game. You get experience points for defeating enemies, gain levels and stronger magic.' FROM games WHERE igdb_id = 79293 ON CONFLICT (game_id, language_code) DO NOTHING;
