INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry Gaiden III: Scripture of the Dark', 'Wizardry Gaiden III: Scripture of the Dark is a Role-Playing game, developed by Sir-Tech Software Inc. and published by ASCII Entertainment, which was released in Japan in 1993. While the first two Gaiden games, Wizardry Gaiden: Suffering of the Queen and Wizardry Gaiden II: Curse of the Ancient Emperor, stuck fairly close to each-other and to Wizardry V: Heart of the Maelstrom, Scripture of the Dark started introducing more radical changes to the formula. This was mostly in the form of incorporating elements of Wizardry VI: Bane of the Cosmic Forge, but retaining the core gameplay derived from Wizardry V.' FROM games WHERE igdb_id = 49144 ON CONFLICT (game_id, language_code) DO NOTHING;
