INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-ressha-de-ikou-4', 98268, '1993-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co796k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqkzk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-Ressha de Ikou 4', 'Not released in Western countries, Take the A-Train IV is the fourth game in the Japanese-made A-Train series, directly following its most popular installment, known in the Western world as simply A-Train. The game plays very similarly to its predecessor, including the interface, the core gameplay system (managing a company, purchasing trains, building railways, influencing city growth, transporting goods, etc.), and characteristic features such as a day/night system, weather effects, season changes, etc., all of which influence the player''s chances to earn money from his networks. A new feature is the possibility to build roads, acquire buses, and plan bus routes. The game offers four different scenarios: a medium-sized metropolitan area, an industrial area, a rural area, and a huge high-tech urban area. Each poses different challenges to the player.' FROM games WHERE igdb_id = 98268 ON CONFLICT (game_id, language_code) DO NOTHING;
