INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('boxing-legends-of-the-ring', 38366, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gqk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5krb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxing Legends of the Ring', 'Boxing Legends of the Ring is a boxing game, developed by Sculptured Software and published by Electro Brain. During fights, it is possible to keep track of the participating boxers'' wellbeing by observing the small portraits of the fighters'' faces at the top of the screen. As the fighters receive punishment, these portraits show injuries such as cuts and bruises, the severity of which indicate the fighter''s health (or lack of). There is also a boxing glove shaped meter at the top of the screen, that indicates how much power a boxer has left in his punches (as in a real fight, the more punches boxers throw, the more tired they become, resulting in weaker punches). The fighters movement about the ring is limited to side-stepping left or right; it is impossible to step back or forward. A variety of punches can be thrown; left jabs, crosses to the head, hooks to the body, and uppercuts to the head (all punches except jabs can be thrown with either hand). It is also possible to throw a limited number of so-called ''super punches'', that are essentially either a right cross or a right uppercut, but with extra power. At the start of each round, each boxer is capable of throwing one super-punch at any time, although it becomes possible to throw one more with each knockdown they score against their opponent. Defensive techniques consist of blocking, dodging, and clinching. Each boxer has three attributes: ''power'', ''stamina'', and ''chin''. A special version was released in Mexico and the American Southwest called Chavez II; the game exchanged the English language words for Spanish and omitted some vocals.' FROM games WHERE igdb_id = 38366 ON CONFLICT (game_id, language_code) DO NOTHING;
