INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onizuka Katsuya Super Virtual Boxing: Shin Kentou-ou Densetsu', 'Onizuka Katsuya Super Virtual Boxing ~Shin Kentou Ou Densetsu~ is a boxing video game, developed by Sting Entertainment and published by SOFEL, which was released exclusively in Japan in 1993. It was licensed and endorsed by Katsuya Onizuka, a former WBA Super Flyweight champion.' FROM games WHERE igdb_id = 44384 ON CONFLICT (game_id, language_code) DO NOTHING;
