INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Sports Competition', 'Top Athletes Battle for Glory! You create an athlete who runs, jumps, and throws! Aim for the world record...and never give up! With 18 events to choose from... With 6 categories, and a total of 18 exciting events, you''ll have a wide choice to train for. Then go on to challenge Olympic Mode in your chose event. you too can be a world record holder! Excitement x 5! Exciting alone, unbelievable with friends! Up to five players can compete at once, for some serious adrenalin action!' FROM games WHERE igdb_id = 37731 ON CONFLICT (game_id, language_code) DO NOTHING;
