INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bloodstone-an-epic-dwarven-tale', 2433, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9nrq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw906.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloodstone: An Epic Dwarven Tale', 'Bloodstone is a 1993 high fantasy role-playing video game developed and published by Mindcraft Software. The game is a prequel to The Magic Candle series and uses the Magic Candle III engine. The game begins with a cut scene of the main character''s clan being attacked by the vicious Taldor (default name "Danat" if male, or "Danta" if female). Then you choose three members for your party and the game begins. The Taldor are goblin-like creatures who seem to be cursed with violent bloodlust. The main objective of the game is to retrieve Khamalkhad and join the warring tribes of the North and South. The game employs an interesting pantheon of gods. The player can go to the resting points of the sleeping gods and receive a permanent skill increase by whispering a prayer to them. The game employs creatures like the Tlengle (Lizardfolk), Humans, Dwarves, Talador, Wizards, and Amazons. Magic is done in an odd way; the amount of a specific spell numbers one to ninety-nine. As the player casts a spell they use up one "use" when they run out of uses they either forget the spell or buy a totem, to learn the specific spell by assigning the character to study the magic.' FROM games WHERE igdb_id = 2433 ON CONFLICT (game_id, language_code) DO NOTHING;
