INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest II', 'Remake of Dragon Warrior II released for the Super Famicom in the Dragon Quest I.II compilation. This remake includes updated graphics that retain the original look, sound of higher quality, and some changes in the gameplay and in the game world: certain locations are larger, some menu commands (such as "Stairs") are omitted, and there is a larger variety of items.' FROM games WHERE igdb_id = 239186 ON CONFLICT (game_id, language_code) DO NOTHING;
