INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smash-tennis', 44106, '1993-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3sjl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc94el.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smash Tennis', 'Smash Tennis is a tennis game that was created by Namcot for the Super Nintendo in 1993. It was released in Europe as Smash Tennis by Virgin Interactive. A North American release of the game wouldn’t be seen until February 2020 where it would be part of the Nintendo Switch Online lineup. The controls of Smash Tennis work similar to other tennis games and especially Namco''s previous tennis game World Court Tennis: the player moves the athlete over the court and presses buttons with the correct timing in order to win the match. This time there is no story mode, but a tournament mode instead. Here the goal is to win the Grand Slam by playing various tournament matches. However. a match only has a single set. There are 20 athletes (both male and female) to choose from which have different advantages and drawbacks.' FROM games WHERE igdb_id = 44106 ON CONFLICT (game_id, language_code) DO NOTHING;
