INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('street-blaster-ii-pro', 119413, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7t3d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6ltm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Blaster II Pro', 'Is a pirated port of Street Fighter II: Championship Edition, made by Cony Soft in 1993. This release only contains the original 8 fighters, with the bosses appearing in later variants. The presentation is more accurate to the real Street Fighter II than the re-releases/hacks that came afterwards. Like Cony''s other games, the AI is considered to be unfairly difficult and is known to frequently spam specials. The special moves themselves are executed differently to the official Street Fighter II, requiring the player to press a direction on the D-pad plus A and B at the same time, with the exception of special moves that require to press a button repeatedly. The ending is a simple credits screen which appears in many of Cony''s other games.' FROM games WHERE igdb_id = 119413 ON CONFLICT (game_id, language_code) DO NOTHING;
