INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyber Sled', 'High-tech tanks meet full blown, first person firepower. Cyber Sled cataplults you to a future where tank warfare resembles forumla one racing on an arena football field. Eleven armored battlesleds play hide-and-seek, then seek-and-destroy; each with enough weaponry to take out the former Soviet Union. Their sole purpose? Blow you to scrap. Blink, and you''re Cyber-Dead.' FROM games WHERE igdb_id = 20626 ON CONFLICT (game_id, language_code) DO NOTHING;
