INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gadget: Invention, Travel & Adventure', 'A surreal first-person adventure game set in an unnamed city facing the end of the world. Gadget: Invention, Travel & Adventure is a notable early 1990s CD-ROM title, praised for its melancholic atmosphere and open-ended, emergent narrative design. It has since gone on to influence many visionary filmmakers, game designers, and visual artists.' FROM games WHERE igdb_id = 73567 ON CONFLICT (game_id, language_code) DO NOTHING;
