INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardian War', 'Welcome to GUARDIAN WAR. This is a story about another world, another time. This was a beautiful world guarded by Goddess Erald. Darkness feared the Goddess Erald, and there was no way that Darkness could enter this beautiful world, until..... GUARDIAN WAR’ -All combats take place with 3D animations. -Gain experience and new powers. -32,000 color 3D graphics. -Fully animated 3D magic effects. -55 3D computer graphic characters.' FROM games WHERE igdb_id = 4314 ON CONFLICT (game_id, language_code) DO NOTHING;
