INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ai Sensei no Oshiete: Watashi no Hoshi', 'Ai Sensei no Oshiete: Watashi no Hoshi is a horoscope simulation game that heavily revolves around the love thematics of fortune-telling. The title roughly translates as Love Teacher Oshiete: My Star, which suggests the game focuses on the astrological aspects of fortune-telling and horoscopes.' FROM games WHERE igdb_id = 48668 ON CONFLICT (game_id, language_code) DO NOTHING;
