INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moles-quest--1', 343208, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sit.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mole''s Quest', 'In Mole''s Quest, the player controls a mole who must navigate moving platforms (similar to elevators) to collect objects and return to the starting point. The game is challenging, with obstacles such as bizarre creatures and platforms that can cause instant failure if jumps are mistimed. Each session is limited to 5 minutes, increasing the game’s difficulty and urgency. The game features simple, colorful graphics typical of early 1990s PC games. Controls are basic, using the arrow keys to move the mole and jump between platforms. Mole''s Quest was included in the Fast Action Paq compilation released in 1993. This compilation was published by Mallard Software Inc. and developed by The Dreamers Guild. It featured a collection of four retro-style games, including Mole''s Quest, BOT, Flak Attack, and Bubble Trouble. In 2002, the compilation was re-released under the name Retro-Action Paq by Wyrmkeep Entertainment Co., which also handled the development of the re-release. However, the original 1993 release was published by Mallard Software Inc.' FROM games WHERE igdb_id = 343208 ON CONFLICT (game_id, language_code) DO NOTHING;
