INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Even More Incredible Machine', 'Do you remember watching with amazement when those cartoon heroes constructed machines to catch someone or start something? Those very complicated Rube Goldberg-like ones with knives, toasters, anvils etc? Or did you ever wonder how it would feel to construct a mouse-powered device to cook some eggs and launch a rocket? Well, the answer is here! Build monkey or mouse-powered machines, use lasers and fire fireworks, start fires using a bowling ball and flint, throw things with anti gravity platforms or a jack-in-the-box or crack open an aquarium with a cat, mouse, alligator, cannon, cheese and more!' FROM games WHERE igdb_id = 70233 ON CONFLICT (game_id, language_code) DO NOTHING;
