INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prime Time Figther', 'Prime Time Fighter is a 2D versus boxing game where you participate in an all weight boxing tournament - as all weight classes have been merged in to the Prime Time Fighter world championship. The game offers six boxers from around the world to choose from, each with their own moves. They are: Tamshing Vaortao from Thailand, Shouichi Kanou from Japan, Michael Eldorado from the USA, Aldebaran Nipper from Canada, Bruce Hasimikov from Rusia and Storm Viper form Brasil. You can win with a K.O. or a technical K.O. over three rounds. It''s possible to play solo or against a friend.' FROM games WHERE igdb_id = 393867 ON CONFLICT (game_id, language_code) DO NOTHING;
