INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: X-Wing', 'Star Wars: X-Wing is the first LucasArts DOS computer game set in the Star Wars universe, as well as the lead title in the X-Wing combat flight simulator game series. The player''s character flies starfighters, including the eponymous X-wing, for the Rebel Alliance as part of a narrative that precedes and parallels the events of Star Wars Episode IV: A New Hope.' FROM games WHERE igdb_id = 168 ON CONFLICT (game_id, language_code) DO NOTHING;
