INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Sun: Shattered Lands', 'Shattered Lands is the first in a series of computer role-playing games based in the highly acclaimed AD&D 2nd Edition DARK SUN game world. You begin the game as a gladiator about to fight in King Tectuktitlay’s Arena in Draj. You must survive that fight, along with many others, and continue onward to escape from the Slave Pens.' FROM games WHERE igdb_id = 2466 ON CONFLICT (game_id, language_code) DO NOTHING;
