INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monopoly--8', 171236, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ubx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdl5v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly', 'Everything you love about Monopoly is now here for the Mac. Classic Monopoly is a mouse click away as you engage in the pursuit of great fortunes. With computer enhanced graphics and billions of different dice sequences it''s never the same game twice. Wheel and deal against the supreme game challenger, your Mac. Or play with up to eight players, in this ultimate computer version of the best selling boardgame of all time. The thrill of buying and selling railroads and properties and collecting rent on Park Place awaits you. Pick a "Chance" card and advance to Boardwalk. Or throw doubles three times and "Go directly to Jail" You can play with the "official" Monopoly game rules, or customize them to fit the way you play at home. But as always, the richest player wins. And both color and black and white versions of the program are included - making it perfect for your desktop Powerbook Macintosh. This is a must for the library of any Mac gamer.' FROM games WHERE igdb_id = 171236 ON CONFLICT (game_id, language_code) DO NOTHING;
