INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bonk 3: Bonk''s Big Adventure', 'Aaagh! What''s that Evil King drool doing back in the Dinosaur Kingdom?! Didn''t Bonk get rid of him last time? Guess not, huh? Now it''s up to our skull-splitting, head-butting, rock-smashing, monster-bashing prehistoric hero Bonk to put an end to Drool''s dastardly deeds once and for all! Watch Bonk grown into huge fire-breathing Bonk or shrink into the Mini-Size Bonk and take on tons of cool new enemies like RocketMan, Robo Turtle and Crazy Lady. Or how about smashing up a few Booga Boogas or Snippies along the way. It''s the ultimate bash-o-rama!' FROM games WHERE igdb_id = 37615 ON CONFLICT (game_id, language_code) DO NOTHING;
