INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-94', 3448, '1993-12-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sg7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kua.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman ''94', 'BOMBERMAN has arrived to restore peace on the planet, which has been split into five parts by an evil hand! In addition to the nine members of the Bomber Family, the character ROOI shows up to lend a hand. Jump on the EGGS that appear from destroyed SOFT BLOCKS, and you can ride one of five types of ROOI. Each ROOI has different special abilitiesuse these well and youll ride to victory! Bombs that turn according to arrows and other new gimmicks have been added to BATTLE GAME, increased to ten stages. Tag-team matches are now possible, ensuring that this game will be a blast! Bomberman ''94 is a video game from the Bomberman series which was developed and published by Hudson Soft for the PC Engine and released on December 10, 1993 in Japan. It was later re-developed by Westone and re-published by Sega as Mega Bomberman on the Sega Mega Drive/Genesis in 1994 in other areas. The PC Engine Bomberman ''94 was later released outside Japan through the Wii''s Virtual Console and the PlayStation 3''s PlayStation Network. The game supports single-player and multi-player modes. In single player, the player navigates several levels of mazes, destroying creatures with bombs. In multi-player mode, players defeat each other with bombs. Bomberman ''94 is the final HuCard title to be made and released by Hudson Soft, the original designers of the PC Engine console.' FROM games WHERE igdb_id = 3448 ON CONFLICT (game_id, language_code) DO NOTHING;
