INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kattobi Road', 'Kattobi Road is a racing game that tunes up a car using a barcode boy. There is a wide variety of cars, from light cars to F1 cars, and there are even more types with barcodes.' FROM games WHERE igdb_id = 340328 ON CONFLICT (game_id, language_code) DO NOTHING;
