INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-journey-into-xanth', 135643, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co84hs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8e9b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Journey Into Xanth', 'A Journey Into Xanth takes place in the magical world of Xanth known from the books of Piers Anthony. The game is a classic interactive-fiction game, with a text parser as the sole user interface. It was developed using a contemporary toolkit (Adventure Game Toolkit v1.3). You are playing a young man named Mim. Like all inhabitants of Xanth, Mim has a unique magical ability, the so-called talent. In his case he is able to conjure a magical mirror which can then be used to talk to any person he wants to, regardless of distance to that person. His talent makes him a quite important member of his local community, the Gap village. He serves as the villages'' liaison to King Trent the ruler of the lands of Xanth, who resides in castle Roogna. Mim regularly corresponds with the King discussing various matters. This serves as the starting point for your adventure, as the latest communication with the King will result into a mission given to Mim.' FROM games WHERE igdb_id = 135643 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 135643 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
