INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Star Wars: The Empire Strikes Back', 'Pursued across the galaxy, you and your Rebel Forces now marshall new strength on the remote ice world of Hoth. Although tracked by probe droids, attacked by ice monsters, and confronted by an army of gigantic Imperial Walkers, you must not give in. You are the Alliance''s only hope. Learn the ways of the Force, then test your skills in this fast-paced, action-packed sequel to the hit game Super Star Wars.' FROM games WHERE igdb_id = 44463 ON CONFLICT (game_id, language_code) DO NOTHING;
