INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tko-super-championship-boxing', 42440, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zfl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TKO Super Championship Boxing', 'A boxing game featuring a Championship mode and a 1 or 2 player exhibition match mode. In the Championship mode, players choose from 1 of the 8 available boxers, and then compete against the other 7 boxers on the road to try becoming the World Champ. Players go toe to toe with their opponents in the boxing ring in 3 minute rounds. The boxers can throw hooks and jabs at each other with the sole intention to knock their opponent down to the canvas by draining all their energy by landing those punches. Each punch thrown costs the boxer some stamina which is indicated by boxing glove icons. If all the boxers stamina is drained, they can no longer throw punches for a little while until they gain some of their stamina back. After each fight is over, players go to the gym to train in various different exercises like skipping rope and bench pressing weights. These exercises increase the players boxer in various areas like speed and power. Options include setting the number of rounds (from 1 to 10) and setting the difficulty level (novice, advanced, and expert).' FROM games WHERE igdb_id = 42440 ON CONFLICT (game_id, language_code) DO NOTHING;
