INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yuyu-hakusho-yamishoubu-ankoku-bujutsu-kai', 37629, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bqo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv5zz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YuYu Hakusho Yamishoubu!! Ankoku Bujutsu Kai', 'Despite its premise, which is reminiscent of a versus fighting game, Ankoku Bujutsukai is an arcade-style shooter. The player selects one of the five characters (Yusuke, Hiei, Kurama, Kuwabara or Genkai), and is then taken to a series of one-on-one shoot-outs in a pre-determined order. The enemy is viewed from a first-person perspective, and the player moves a cursor to aim and shoot. The gameplay system is fairly simple, allowing the player to execute three types of attacks: regular shots, charged shots, and special attacks of limited quantity. Points are received for winning fights and can be used to raise the characters'' hit points, speed, or number of special moves.' FROM games WHERE igdb_id = 37629 ON CONFLICT (game_id, language_code) DO NOTHING;
