INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blake Stone: Aliens of Gold', 'You''re pitted against Dr. Pyrus Goldfire. He''s found a way to replicate pure gold, which he''s using to fund his maniacal plan. Goldfire has built six highly-secure, futuristic locations where his creations are being hatched. It''s up to you to penetrate his security and stop him at all costs.' FROM games WHERE igdb_id = 8489 ON CONFLICT (game_id, language_code) DO NOTHING;
