INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-great-battle-iii', 66671, '1993-03-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co523c.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great Battle III', 'The Great Battle III is a scrolling brawler featuring the F91 Gundam, Kamen Rider, Ultraman and the Great Battle series''s original character Fighter Roar. The game is set in a fantasy world and the characters all use medieval weaponry in battle. The game is the third in the series of Great Battle brawler/shooter games, and the seventh Compati Hero Series game for the Super Famicom (of seventeen).' FROM games WHERE igdb_id = 66671 ON CONFLICT (game_id, language_code) DO NOTHING;
