INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3-count-bout', 6734, '1993-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hhh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar380z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3 Count Bout', '3 Count Bout is a one-on-one fighting game. Choose from ten wrestlers who have their own power attacks. There are ten rounds in the game, and each one of them has you fighting other wrestlers that are much tougher than the previous ones. You defeat each one by biting, kicking, and performing other moves to the point where their damage meter is empty. But just because it is empty doesn''t mean that you win. You have to pin him for the infamous-three count. Also features competitive play and tag match battles. 3 Count Bout by SNK Corporation attempts to take you into the world of professional wrestling by giving you control of one of many different wrestlers as you fight both in the ring and in the seedy underworld in your quest to become an accomplished wrestling champion. Choose from one of ten different characters, each with his own strengths and weaknesses, and employ your wrestling moves using a combination of three buttons. There are also a number of hidden moves and combinations which can be unlocked for even greater variety in the gameplay. When you have your opponent on the mat, keep him there until the count of three and you''ve won the match. In two-player mode, you can either take on your opponent in a match or wrestle tag team. This game uses the Neo-Geo MVS cartridge system.' FROM games WHERE igdb_id = 6734 ON CONFLICT (game_id, language_code) DO NOTHING;
