INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('illusion-of-gaia', 3016, '1993-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kyi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fhfxvvola0s0ffhluc3v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illusion of Gaia', 'Journey into the dark side of an ancient civilization. Radiating an ominous light in its path, the Chaos Comet threatens the existence of the planet. Battles erupt and a tentative peace is returned to the lands. Danger lurks as the Chaos Comet orbits and dreadful beasts lie awaiting. In the Age of Exploration a boy named Will is born. Tragedy strikes during an expedition to the Tower of Babel separating Will from his father. Telekinetic forces awaken as Will returns to South Cape. Armed with his transformation abilities of two great warriors, Will must save the planet. Gaia, Will''s guiding spirit bestows magical powers and advice along his journey. With the help of his friends Will must battle relentless enemies and solve the puzzles of the ancient ruins. Patience and knowledge are essential to reunite this father and son.' FROM games WHERE igdb_id = 3016 ON CONFLICT (game_id, language_code) DO NOTHING;
