INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thunder-dragon-2', 40247, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/iufjunexlrkbtvjeocjy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckelq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Dragon 2', 'Thunder Dragon 2 is a vertical arcade shooter, developed and published by NMK in 1993. The game uses variable rate scrolling (the screen scrolls at different speeds or not at all), and is played from a top-down view. Unlike space shooters, Thunder Dragon 2 is played in-atmosphere on a single world with contemporary airplanes. The game contains eight stages, with popcorn enemies and ships with varying degrees of durability throughout. Each stage culminates in a boss fight, preceded by a warning. The player chooses between two different ships, a slow but powerful ship on the player 1 side, and a fast but weak ship on the player 2 side. Scoring is accomplished through enemy destruction, accumulation of medals dropped by enemies, and special bonus awards for completing specific tasks.' FROM games WHERE igdb_id = 40247 ON CONFLICT (game_id, language_code) DO NOTHING;
