INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clown', 'Tom Clown is an unlicensed game for the Sega Mega Drive developed by AV artisan and published by Realtec in 1993. Tom Clown Circus is an interpretation of the game with the Atari 2600. The game is pretty hardcore. Music is poor. A "diversity" levels - a typical Arkanoid without bonuses. It was originally bundled on floppy with Realtec''s copier and was eventually put out on an extremely small amount cartridges.' FROM games WHERE igdb_id = 46676 ON CONFLICT (game_id, language_code) DO NOTHING;
