INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yume-maboroshi-no-gotoku', 37753, '1993-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/emar3gpkpqmqlvbx84ia.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume Maboroshi no Gotoku', 'A Super Famicom RPG set in a version of feudal Japan. It was developed by TOSE and published by Intec. Yume Maboroshi no Gotoku ("A Dreamlike Illusion", roughly) is an RPG set in a version of Sengoku era Japan. It otherwise plays like a standard JRPG, with a turn-based system that uses large enemy sprites in the center of the screen a la Phantasy Star or Dragon Quest. The game was one of two games ever published by Intec for the Super Famicom. They usually worked with the Turbo CD/PCE-CD system. It was never localized into English or released outside of Japan.' FROM games WHERE igdb_id = 37753 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 37753 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
