INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capture the Flag', 'MS-DOS game released in 1992 by Richard Carr. First game to use the principle of "Capture The Flag." It is a strategy game, where two teams try to capture the other''s flag before the other team captures theirs. The game takes place on a large field, with various types of terrain. You control one of the teams; the other team can be either controlled by the computer, or by another human player.' FROM games WHERE igdb_id = 73612 ON CONFLICT (game_id, language_code) DO NOTHING;
