INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Underground', 'Computer Underground (also known as C.U.) is a game published in 1993 by Haxoft, the theme is cyberpunk / dark sci-fi, puzzle-solving. It features a role-playing (rpg), simulation genre and uses a perspective.' FROM games WHERE igdb_id = 2458 ON CONFLICT (game_id, language_code) DO NOTHING;
