INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El-Fish', 'A fish and aquarium simulator, El-Fish lets your catch, breed, evolve, and even mutate tropical fish, then render them and let them loose in an aquarium that you design. Except for a few pre-canned graphics and animations, all fish, plants, and even backdrops and floor gravel in El-Fish are generated by the user using genetic algorithms that simulate real life in both appearance and movement.' FROM games WHERE igdb_id = 72089 ON CONFLICT (game_id, language_code) DO NOTHING;
