INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Explorer II', 'This CD sequel to Dungeon Explorer plays exactly the same as the first game. You chose your character from a variety of fantasy stereotypes and set forth in a Gauntlet-esque adventure. The CD format allows a greater quantity and variety of levels to compliment the storyline, with new areas and characters becoming open to you as you progress.' FROM games WHERE igdb_id = 42022 ON CONFLICT (game_id, language_code) DO NOTHING;
