INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Maulers', 'The three main protagonists are Kotetsu, Anne and Eagle, members of the "Ultimate Task Force". A trio of evil villains known as the Happy Droppers unleashes a swarm of monsters to terrorize countries of the world, sending the three heroes on a mission to end the disaster and defeat the evil masterminds.' FROM games WHERE igdb_id = 39541 ON CONFLICT (game_id, language_code) DO NOTHING;
