INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakline', 'Using a paddle, bounce a ball up and down to break blocks on the game field, which can in turn activate several special abilities (e.g. releasing several balls at once or a ball which cuts through solid blocks). The levels include gimmicks like teleporters or bumpers, as well as a training mode in which you can select the individual levels.' FROM games WHERE igdb_id = 147279 ON CONFLICT (game_id, language_code) DO NOTHING;
