INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zen-intergalactic-ninja', 48251, '1993-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9if8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar45su.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen: Intergalactic Ninja', 'IF YOU LIKE FIGHTING DIRTY, YOU''RE GONNA DIG ZEN! The greatest environmental disaster in human history is about to hit your backyard. But you''re not backing down, because you''re Zen, a cold-blooded Ninja warrior who''s come to Earth to clean the clock of Lord Contaminous and his crud-loving cronies. But wasting these slimeballs won''t be easy. Because they''ll spew forth the most hazardous graphics ever to wreak havoc on your NES. We''re talking horizontal, vertical and 3/4 view scrolling that will give you a whole new perspective on acid rain, oil spills and ozone-ravaging smog. And wait till you see the fluid character movements. They''re hotter than a uranium-oozing nuclear meltdown! There are 12 total levels, each with its own ecological enemies, toxic traps and pollution-fighting objectives. You''ll battle oil rig fires, trying to save trapped workers. Use your Photon-Stick to zap gaseous garbage men on a high-speed plutonium mining car ride. Vertical jump through two separate screens to reach a venomous vixen who''s single-handedly scorching the rainforests. And spin kick Smogger, a smoked-out scum of the Earth. Finally, try to survive a rescue mission stage. Rack up points in the bonus recycling level. And slash through 6 subgames that will lead you to the feet of Lord Contaminous, who you must dispose of before he trashes every living thing on the face of the Earth. For 1 Ninja Master.' FROM games WHERE igdb_id = 48251 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48251 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
