INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slam!', 'Slam! is a Windows-based (3.x) simulation of the popular table game of air hockey. Players can customize opponents skills with the ability to change aggressiveness and quickness from 1 to 99, change view angle from zero to 90 degrees, turn sound on/off and have a choice of default color or monochrome default (black and white) coloring. You control your paddle with the mouse, and by right clicking players can enter the options menus.' FROM games WHERE igdb_id = 94696 ON CONFLICT (game_id, language_code) DO NOTHING;
