INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prize Fighter', 'Prize Fighter is a FMV boxing game which puts the player in the body of a boxer known as "The Kid" and must face off against four opponents: Honeyboy Fernandez, Mega Joe Falco, Rex Hawkins, and, the ultimate challenge, Nuke "The Duke" Johnson, over the course of two CDs.' FROM games WHERE igdb_id = 5424 ON CONFLICT (game_id, language_code) DO NOTHING;
