INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Special Forces: Operation Blood II', 'It is an on-rails first-person shooter released in 1993 for Atari. It is a sequel to 1992''s Operation Blood. The game has the same gameplay mechanics as the predecessor, meaning that the player cannot control the camera as it moves by itself from left to right or vice versa. The player must kill as many enemies on screen as possible while avoiding killing civilians or medics.' FROM games WHERE igdb_id = 137424 ON CONFLICT (game_id, language_code) DO NOTHING;
