INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1990: Die 1993''er Edition', '1990: Die 1993''er Edition is an expanded re-release of 1990. The changes are mostly technical, e.g. many drawn graphics were replaced with digitized photographs and there is in-game music. There are no significant changes regarding gameplay and user interface.' FROM games WHERE igdb_id = 38854 ON CONFLICT (game_id, language_code) DO NOTHING;
