INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buubuu Mario', 'Buubuu Mario (Buzzing Mario) is a common Mario arcade-ride hybrid game released only in Japan by Banpresto. Very little is known about it and can only be assumed through video playthroughs. The game is a combination kiddy ride/video game starring Mario and Yoshi. The player sits in front and must steer the car to avoid boulders in the road, while sculpture representations of Mario and Yoshi sit in back.' FROM games WHERE igdb_id = 131953 ON CONFLICT (game_id, language_code) DO NOTHING;
