INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eliminate Down', 'Eliminate Down is a 1993 scrolling shooter video game developed by Aprinet and published by Soft Vision International for the Sega Mega Drive. The game was released in Japan on June 25, 1993, and in South Korea in 1993. Eliminate Down gives players immediate access to three directional-based weapons that could all be powered up as they fought strange alien enemies through eight enormous levels.' FROM games WHERE igdb_id = 46176 ON CONFLICT (game_id, language_code) DO NOTHING;
