INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bram Stoker''s Dracula', 'Bram Stoker''s Dracula is game loosely based on the 1992 film of the same name. It was released simultaneously for multiple consoles and while the plot remains largely the same, there are differing styles of gameplay and graphics across platforms. This version of Bram Stoker''s Dracula is a platformer where you play as the young lawyer named Jonathan Harker. Harker must free himself from Count Dracula''s captivity, follow him to London, and end his reign of terror.' FROM games WHERE igdb_id = 14340 ON CONFLICT (game_id, language_code) DO NOTHING;
