INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zavas-ii-the-prophecy-of-mehitae', 232826, '1993-02-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co61kr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scknto.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zavas II: The Prophecy of Mehitae', 'The follow-up to Zavas is, like its predecessor, a fantasy role-playing game with Japanese anime-like aesthetics, but more Western-oriented free-form gameplay with more emphasis on character development than on a character-driven plot. Through a series of choices the player make the protagonist (always named Majon, but with different family names) to be a prince, the son of a merchant, or the son of a fisherman. In the beginning the player character undergoes a series of trials (which may include arcade-style mini-games, mathematical tasks, etc.) which determine his eventual attributes and also follow his growth until he turns sixteen and embarks on a quest to find companions and defeat an evil sorcerer in accordance with an ancient prophecy. Though the game has a traditional overworld with towns, hostile areas, and fairly simple turn-based battles, many of its gameplay features deviate from the standard Japanese template. Every NPC can be approached with different attitudes (including bribe and usage of items), and often a specific attitude is needed to further the hero''s goals. Money can be earned and managed through various activities. Experience points are awarded for conversations and other actions besides combat. An important factor is the party''s stamina: a certain amount of it must be reached in order to access key plot-advancing locations, and building up stamina through side quests and other actions occupies a considerable portion of the gameplay. The protagonist has a ship at his disposal from the beginning of the game, and it is possible to physically sail across the sea and access any location, provided the stamina level is high enough.' FROM games WHERE igdb_id = 232826 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 232826 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
