INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ren & Stimpy Show: Buckeroo$!', 'Stimpy invents the Gametron 5000 Moneymaker which is the first video game machine in the world that rewards the player with money. Ren, who is always on the lookout to get rich, eagerly gets to playing with the video game system on the quest to earn big bucks. In the game, you control Ren & Stimpy through various side scrolling levels which are based on different episodes of the cartoon show. Episodes the levels are based on are Space Madness,Out West, and Robin Hoek.' FROM games WHERE igdb_id = 48209 ON CONFLICT (game_id, language_code) DO NOTHING;
