INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beetlejuice: Horrific Hijinx from the Neitherworld!', 'Beetlejuice: Horrific Hijinx from the Neitherworld! is a video game created by Rare and published by Acclaim Entertainment for the Nintendo Game Boy in 1992. It is based on the Beetlejuice animated television series. The game begins with the player taking control of Beetlejuice as he attempts to get rid of all the ghosts that he invited into Lydia Deetz''s house (where she lives with her father and step-mother). He must rescue Lydia from the evil Astoroth. Using bio-exorcist magic, players must defeat undead creatures through the cemetery and inside the Neitherworld.' FROM games WHERE igdb_id = 80889 ON CONFLICT (game_id, language_code) DO NOTHING;
