INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancient-magic-bazuu-mahou-sekai', 15892, '1993-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kx8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ry2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Magic: Bazuu! Mahou Sekai', 'Ancient Magic is a story RPG where you play a young boy or girl whose father, Ricardo, was a powerful mage. Determined to follow in your father''s footsteps, you make a vow to your mother to attend the Magic School in Selas. When starting, you can choose the occupation of the character, and you can choose a teacher from among some of the magicians while playing the game. You are joined on your journey by Feyr, a bard, Romal, a knight, Lot, a priest, and many others. As you progress as a mage, you are sent on quests to explore ruins and uncover spells. Meanwhile, a mysterious man named Kuroizel and the evil Veranede Tribe are plotting something, and it''s up to you to find out what. This old school RPG is strictly fantasy. It has the nostalgic feel of a Dungeons and Dragons campaign. See if you can spot the advert by developer and publisher Hot-B for another of their products in the game! Despite its rather pedestrian roots, the game takes several surprising twists towards the end, and is generally worth sticking it out even if the wrap-up (or lack thereof) is a bit of a let down. As a note, there’s more game past “THE END.” Also as a note, do set your window speed to “fast” in the in-game options menus - it’ll improve your experience dramatically.' FROM games WHERE igdb_id = 15892 ON CONFLICT (game_id, language_code) DO NOTHING;
