INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Football Trivia Challenge', 'NFL Football Trivia Challenge is a trivia game with an National Football League license. Either player can pick his favourite team to play with. TV commentators Pat Summerall and Tom Bookshier describe various situations in play accompanied by 1200 images and 300 Full Motion Video clips. 1500 multiple choice questions are waiting to be answered in the game. For each correct answer the player gains yardage in the game and increases his chances of scoring a point. The player with most points after 60 questions wins the game. There are three different difficulty levels to play at.' FROM games WHERE igdb_id = 46414 ON CONFLICT (game_id, language_code) DO NOTHING;
