INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maten-no-soumetsu', 46073, '1993-12-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vpw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckauj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maten no Soumetsu', 'Maten no Soumetsu tells the story of a young boy (you can name him as you like) who was found in the forest by a warrior named Zafan. Zafan takes the boy into his home, where he grows up, unaware of this story. When he reaches the age of sixteen, Zafan dies, attacked by monsters. He sends his adoptive son to visit the king of the country, to follow the way of the warrior - and perhaps to discover his true origins... This is a traditional Japanese RPG set in a medieval environment, with randomly appearing enemies whom you fight in turn-based style, viewing the battle field from first-person perspective. During your journey through the country you''ll meet other characters who will join your party. There is a night/day cycle in the game.' FROM games WHERE igdb_id = 46073 ON CONFLICT (game_id, language_code) DO NOTHING;
