INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take a Break! Pinball', 'Take a Break! Pinball contains a set of 8 pinball tables based upon various popular Sierra games: Larry''s Big Score (Leisure Suit Larry series), Lots in Space (Draxon), Flipped Out Willy (The Adventures of Willy Beamish), Nova 9 (Draxon), Planet Xenon in the Beginning (Space Quest series), Quest for Daventry (King''s Quest series), Reformation Day (Space Quest series) and Spaced Travel (Space Quest series)' FROM games WHERE igdb_id = 73688 ON CONFLICT (game_id, language_code) DO NOTHING;
