INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Follow the Reader', 'Follow the Reader is an abandoned adventure game for children, set in the Disney universe featuring Disney Characters. Practice your reading through an interactive storybook experience and live one day as Mickey Mouse! Select different actions to be read by a narrator as Mickey does the actions chosen by the player. Players can save the game and then load and watch the story they''ve helped create take place without them pressing on anything.' FROM games WHERE igdb_id = 191528 ON CONFLICT (game_id, language_code) DO NOTHING;
