INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jimmy Connors Tennis', 'Jimmy Connors Tennis is a tennis simulation video game developed by NMS Software for the Nintendo Entertainment System and the Game Boy, and published by Ubi Soft in 1993. The game features the name and likeness of American world-number-one tennis champion Jimmy Connors. Ubisoft published Jimmy Connors Tennis two years after Connors'' late-career comeback in the Men''s Singles division at the 1991 US Open, where he reached the semifinals. The player can compete in an ATP World Tour at one of three difficulty levels, or just practice hitting tennis balls. Two players may play competitively. The Game Boy version of the game allows two-player competitive play over a Game Link Cable. In french markets, Jimmy Connors was replaced with Yannick Noah as the title athlete.' FROM games WHERE igdb_id = 40845 ON CONFLICT (game_id, language_code) DO NOTHING;
