INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien3: The Gun', 'Using cabinet mounted guns you and another player blast away the Aliens in an attempt to save the prison planet. You are also given a limited number of grenades to use when the going gets tough. The gameplay is very close to Sega’s other lightgun games from the period such as Gunblade and Jurassic Park. This game was based on the movie of the same name.' FROM games WHERE igdb_id = 38520 ON CONFLICT (game_id, language_code) DO NOTHING;
