INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cheetahmen', 'Unlike the NES version of Cheetahmen. The Sega Genesis one instead has the same background on all levels, and you need to collect Cheetah Icons from trees or ground areas, and battle snakes, bats, white rhino, hyena, scavenger, and more creatures as you try to get the Cheetah Icons. In level 1 you play as Hercules, then Apollo in level 2, and finally Aries in level 3. Finally, after those 3 levels, the game is beaten.' FROM games WHERE igdb_id = 245125 ON CONFLICT (game_id, language_code) DO NOTHING;
