INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bajoran Mercenary Adventure!', 'Bajoran Mercenary Adventure! is a single player, interactive fiction game that was developed with the Adventure Game Toolkit. You are a Bajoran mercenary contracted to find the ''orbs'' that was stolen by the evil Cardassians. Your sources tell you that the orbs are kept in a cave, though it is rumored that some who enter are never seen again. Your mission is to retrieve as many orbs as possible and return (SAFELY!)' FROM games WHERE igdb_id = 116807 ON CONFLICT (game_id, language_code) DO NOTHING;
