INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon: Yume Dorobou to 7-nin no Gozans', 'Doraemon: Yume Dorobou to 7-nin no Gozans is a 1993 platformer by Sega for the Sega Mega Drive tying into the Doraemon media franchise. B jumps. C shoots your gun, which stuns enemies so you can safely jump on them and use them as platforms. The longer you hold C, the more powerful your shots get; sufficiently powerful shots can destroy enemies.' FROM games WHERE igdb_id = 45730 ON CONFLICT (game_id, language_code) DO NOTHING;
