INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakajima Satoru Kanshuu: F1 Super License', 'Nakajima Satoru Kanshuu F1 Super License is a 1992 racing game by Varie for the Sega Mega Drive and the third Mega Drive game in their Nakajima Satoru Kanshuu games, following F1 Hero MD. This game is a 2D racer, like F1 Grand Prix and unlike F1 Hero MD. B accelerates. This game adds a save system, allowing you to save your progress over the course of the prix.' FROM games WHERE igdb_id = 45718 ON CONFLICT (game_id, language_code) DO NOTHING;
