INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Downtown River City Baseball Story: Play Ball, Kunio!', 'Tatsumi Tachibana, An honor student and a superb athlete, is the team captain of Nekketsu High''s Baseball team. An injury on his shoulder bars him from leading Nekketsu High to Japan''s National High School Baseball Tournament. His girlfriend and team manager of Nekketsu High''s Baseball team, Rika Asano, is heartbroken and unable to fulfill her duties as team manager. This motivates Sugata Sanjuro, who has a crush on her, to lead the Nekketsu team in the baseball tournament. Todou Kounosuke holds a conference and announces that Japan''s National High School Baseball Tournament will commence, and Nekketsu High will be lead by Sugata. Will Nekketsu be able to defeat Reihou Academy and the other teams with Kunio nowhere to be found?' FROM games WHERE igdb_id = 38277 ON CONFLICT (game_id, language_code) DO NOTHING;
