INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dual-orb', 15906, '1993-04-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4k2b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ylqzrmsowf5nfpd8snou.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dual Orb', 'In an alternate reality, in a parallel world, there are humans just like in the universe we dwell in. Those humans used to co-exist peacefully with animals, fairies, and dragons - other inhabitants of the world. The dragons were the wisest, most ancient, and most powerful race of all. But humans feared their wisdom and their strength, and lost contact to them, destroying the balance in the world. Now, only a few dragons remained, and their whereabouts are shrouded in mystery... You control Ralph, a young fighter apprentice who lives with his old master in a small house near a village. It is the day of your graduation, and the master sends you to meet a very important person. When you arrive at this person''s hut, you are spoken to by the spirit of a mighty dragon, the creator of the universe! You, the young adventurer, is chosen to stop an evil spirit who tries to destroy the universe, and as a token you receive a magic Orb, which contains the soul of the great dragon. And there your adventure begins... Dual Orb is a traditional Japanese-style RPG with turn-based combat viewed from first-person perspective. As Ralph ventures further on his journey, he discovers companions who will help him on his quest, and join his party.' FROM games WHERE igdb_id = 15906 ON CONFLICT (game_id, language_code) DO NOTHING;
