INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tao Taido', 'Thid game takes place on Earth, where eight martial artists from around the planet compete against each other to fight and defeat the legendary master and reveal the secrets of Ta•o Taido. The game appears to be similar to other 2D versus fighting games during its release, but has different gameplay. The player''s character fights against their opponent in single round matches in a single player tournament mode with the computer or against another human player, while using very simplistic commands that summon charging attacks.' FROM games WHERE igdb_id = 39585 ON CONFLICT (game_id, language_code) DO NOTHING;
