INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arnie II', 'ARNIE returns for four punishing missions requiring the deadly skills of a professional soldier.  A full assault on the enemy''s base, gathers the latest high technology weapons, including Machine Pistols, M1 Rifles, Colt Commandos and the Uzi Light Machine Gun, for use in the destruction of an awesome weapon of mass destruction.  High levels of armed resistance are expected....' FROM games WHERE igdb_id = 41009 ON CONFLICT (game_id, language_code) DO NOTHING;
