INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run Saber', 'Run Saber is a 1993 side-scrolling action game developed by Horisoft and published by Atlus for the Super Nintendo Entertainment System. The game was released in North America on June 8, 1993, and in Europe in 1993. Run Saber features side-scrolling fighting as the two main heroes, Allen and Sheena, the Run Sabers, fight to save the planet. The gameplay is very similar to Strider.' FROM games WHERE igdb_id = 22358 ON CONFLICT (game_id, language_code) DO NOTHING;
