INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Nicklaus'' Power Challenge Golf', 'Power Challenge Golf is a golf simulation game, based on Accolade''s own Golf & Course Design from the year prior, and featuring both of the courses from that title (Sherwood and English Turn) as well as one additional new course (Baltusrol). The game offers stroke and skins play for up to four players, as well as a driving range and a practice mode. The course editor from the PC version, however, has been removed.' FROM games WHERE igdb_id = 46532 ON CONFLICT (game_id, language_code) DO NOTHING;
