INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Next Generation', 'Star Trek: The Next Generation is divided into a series of missions. Players will start on the main screen of the bridge and from there can access Navigation, Tactical, Operations, Engineering, Transporter Systems and Mission Control. Mini-games are sometimes used to complete certain ship functions (such as rerouting power to the shields).' FROM games WHERE igdb_id = 48239 ON CONFLICT (game_id, language_code) DO NOTHING;
