INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gordo 106', 'Gordo 106 is a 1993 platform video game developed by Tenth Planet Software and published by Atari Corporation in North America and Europe exclusively for the Atari Lynx. Set in the installations of N. Human Laboratories, players assume the role of an exploited laboratory monkey named Gordo, who unintentionally gained intelligence as a result of experimentation with radiation in order to free other animal test subjects and escape from the building, while defeating scientists and employees of the complex along the way. Its gameplay consists of platforming and exploration with a main three-button configuration.' FROM games WHERE igdb_id = 40837 ON CONFLICT (game_id, language_code) DO NOTHING;
