INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Mahjong Kiwame', 'Pro Mahjong Kiwame is a Super Famicom mahjong game from Athena and the first of their Pro Mahjong Kiwame series, which would go on to have many sequels for various systems (including Pro Mahjong Kiwame GB for Game Boy). The game is touted as a serious mahjong game, requiring a certain level of skill from its players. Unlike many early video game mahjong games, the game allows for the full four participant experience rather than the truncated one-on-one set-up.' FROM games WHERE igdb_id = 138094 ON CONFLICT (game_id, language_code) DO NOTHING;
