INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Edge', 'Dark Edge is a 1992 fighting game by Sega for the Sega System 32. It uses sprite scaling to simulate a 3D playfield, meaning it predates Virtua Fighter as a 3D fighter by about a year (though the 3D in Virtua Fighter isn''t simulated, but rather true rendered 3D graphics). You can play as either warriors or monsters, but otherwise this is a typical fighting game with a dedicated jump button (as Up moves back). Although the title screen reads "1992", the arcade game was first sold in early 1993.' FROM games WHERE igdb_id = 39413 ON CONFLICT (game_id, language_code) DO NOTHING;
