INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Slapshot', 'A generic 5-on-5 hockey game endorsed by ''Mr. Hockey'' Gordie Howe. There are 32 international teams to choose from in exhibition and tournament. The gameplay features realistic hockey action with penalties and up close fights. There are 10 or more pages of hockey stats available during games.' FROM games WHERE igdb_id = 42451 ON CONFLICT (game_id, language_code) DO NOTHING;
