INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Off Road: The Baja', 'Super Off Road: The Baja is a sequel of Super Off Road. Unlike its predecessor which uses an isometric top-down view of a single-screen track, this arcade racing game is made specifically for the SNES and uses its Mode 7 hardware for a 3D racing experience with a 3rd person perspective.' FROM games WHERE igdb_id = 42575 ON CONFLICT (game_id, language_code) DO NOTHING;
