INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shuyaku Sentai Irem Fighter', 'Shuyaku Sentai Irem Fighter is a 1993 strategy video game developed and published by Irem exclusively in Japan for the Nintendo Game Boy on July 30, 1993. It features characters from four of Irem''s franchises: R-Type, Mr. Heli, Ninja Spirit, and Hammerin'' Harry.' FROM games WHERE igdb_id = 210800 ON CONFLICT (game_id, language_code) DO NOTHING;
