INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamic Country Club: 3D Golf Simulation', 'Dynamic Country Club is a 1991 arcade golf game by Sega released on Sega System 24 hardware. Both floppy disk-based and ROM board-based versions of the game exist. The game presents itself in a pseudo-3D setting a la T&E Soft golf games like Pebble Beach Golf Links where the screen slowly redraws itself at certain intervals in your swing. A game with the same name for the Sega Mega-CD was produced, but only released in Japan. Whether or not this is the same game is unknown.' FROM games WHERE igdb_id = 45873 ON CONFLICT (game_id, language_code) DO NOTHING;
