INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laserstrike', 'Laserstrike is a single-player, shareware, puzzle game. The object of the game is to fire a laser at a target and hit it twice to complete a level. Lasers can only travel in straight lines and so the player must use lasers and other canons to move blocks and mirrors in order to achieve the task. The full version of the game has twenty two puzzles and seven coaching or tutorial puzzles.' FROM games WHERE igdb_id = 122567 ON CONFLICT (game_id, language_code) DO NOTHING;
