INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fausseté Amour', 'This is the adventures of Koruku Ransu, a young blue-haired warrior. The evil lord Goat Bone has kidnaped her beloved sister and also controls the minds of most of her best friends. Koruku wears a strong pink armor Through seven long stages, one of Kokuru''s friend awaits at the end of each one of them - however, she will have to defeat their dark side first and free their controlled minds.' FROM games WHERE igdb_id = 37628 ON CONFLICT (game_id, language_code) DO NOTHING;
