INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Undoukai', 'Mario Undoukai (Mario Sports Festival) is a Mario arcade game released only in Japan. Like Buzzing Mario, very little is known about it. The game is a dancing game geared toward small children. It is one of the only two dancing games in the Mario series and is very similar to the other one, Dance Dance Revolution: Mario Mix, but there are two neutral foot spaces and no 2-player mode.' FROM games WHERE igdb_id = 132029 ON CONFLICT (game_id, language_code) DO NOTHING;
