INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend - The Four Crystals of Trazere', 'Legend is an isometric fantasy role-playing game released in 1992 for the PC, Amiga, and Atari ST.  In the game, the player controls four adventurers on a quest to save the land of Trazere from an ancient, re-awakening evil. In 1993, Mindscape released a sequel, Worlds of Legend: Son of the Empire.' FROM games WHERE igdb_id = 37131 ON CONFLICT (game_id, language_code) DO NOTHING;
