INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyuukyoku Sentai Dadandarn', 'A trio of supervillains unleashes an army of gross mutants on earth on order to start an alien invasion. Our only hope is the trio of superheroes known as the ''Ultimate Task Force''. Squash the evil mutants and put an end to the alien menace. Features excellent graphics & sound as well as plenty of moves to find!' FROM games WHERE igdb_id = 40219 ON CONFLICT (game_id, language_code) DO NOTHING;
