INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wimbledon II', 'You started out at the bottom, an unknown name in a field of highly talented players. You worked your way up the ranks, playing in America, Australia and France. And now, the big day... the day you take on the best tennis players in the world for the Wimbledon Open Cup!' FROM games WHERE igdb_id = 46105 ON CONFLICT (game_id, language_code) DO NOTHING;
