INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-red-crystal-the-seven-secrets-of-life', 198262, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ok6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Red Crystal: The Seven Secrets of Life', 'You are in the land Darkmoore which is reigned by the evil Lexnor. And because you are playing an RPG you have to defeat him. For this purpose you travel through Darkmoore to conquer dungeons and maximize your fame. You can choose between five classes. The screen is divided into two parts. On the left side is always our hero, the right side is reserved for various indexes like a map. This is, if you play alone. Quite unusually for RPGS of its time you can play the game with a friend - the second player is seen on the right side of the screen. Before every fight you can try to bribe your enemy.' FROM games WHERE igdb_id = 198262 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 198262 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
