INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyborg-justice', 46236, '1993-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5l1k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmirz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyborg Justice', 'You are a member of the Galatic Unity Agency on routine patrol in deep space when your patrol ship is damaged after accidently passing through a meteor storm and starts to lose control, smashing into a nearby planet and blacking out. The next thing you remember you are rummaging through scrap metal and welding together steel to make parts for weapons. You have become a cyborg slave in a munitions factory for the Cydrek Federation, a twisted machine with a human brain, unable to comprehend your situation, clouded by cybernetic programming until one day your human side finally starts to break through. You remember everything and realize that the Cydrek Federation is building an army to take on the G.U.A. and you must stop it. You must take on the entire Federation using your new cybernetic body and stop them from taking over the universe.' FROM games WHERE igdb_id = 46236 ON CONFLICT (game_id, language_code) DO NOTHING;
