INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoJo no Kimyou na Bouken', 'The first JoJo-centric game released, it was never localized outside Japan. Production was done under Shinji Hashimoto. The game features some notable alterations to the story of Stardust Crusaders. The player controls the protagonists of Stardust Crusaders in a combination of Point and click adventure and classic third-person RPG. It is sometimes also referred to as a side-scrolling RPG.' FROM games WHERE igdb_id = 221257 ON CONFLICT (game_id, language_code) DO NOTHING;
