INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Gate', 'A terrifying evil is threatening the safety of your planet. Hordes of monsters are advancing through the Alien Gate with one objective in mind - the destruction of your world! Only you can ward off this danger. As a rocket fighter pilot, your coolheadedness will be tested to the utmost. The last battle has begun.' FROM games WHERE igdb_id = 46611 ON CONFLICT (game_id, language_code) DO NOTHING;
