INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer 94: Road to Glory', 'The players are drawn large and there is a large scanner to assist with long passing. The standard mode has the ball sticking closely to the feet, which makes mazy runs upfield a common strategy. There are 64 international teams on offer, with a European-style knock-out cup competition included. Many different formations and strategies are offered.' FROM games WHERE igdb_id = 42428 ON CONFLICT (game_id, language_code) DO NOTHING;
