INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freddy Pharkas: Frontier Pharmacist', 'The adventures of Freddy Pharkas, a pharmacist living in Coarsegold in the 1800s, where he moved to cover up his past as a former gunslinger who quit when he got his ear shot off by a rival. When a string of strange happenings and a pack of wild outlaws come to town and threaten to run everybody out; Freddy must take out his guns once again and defend the town and the woman he holds dear.' FROM games WHERE igdb_id = 110 ON CONFLICT (game_id, language_code) DO NOTHING;
