INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Pinball', 'Epic Pinball is the ultimate PC pinball collection in the true-to-life 1990''s pinball style. Originally released as shareware on floppy disks, the first release included 8 tables: Android, Pot of Gold, Excalibur, Crash & Burn, Magic, Jungle Pinball, Deep Sea and Enigma. Later versions would contain an updated version of Android called "Super Android".' FROM games WHERE igdb_id = 50763 ON CONFLICT (game_id, language_code) DO NOTHING;
