INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancients-death-watch', 12391, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p1xeuv6xv1bjtczujtma.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/niyokscnbgeonzf4ssfj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancients: Death Watch', 'Ancients 1: Death Watch is a mystical fantasy role-playing game, bringing players deep in the underground to do battle with bizarre monsters and find untold riches in and beneath the city of Locklaven.  The player uses keyboard or mouse to control a party of four explorers who journey together and must work as a team to ward off the many inhabitants of the dungeon. Said dungeon consists of several levels with increasing difficulty and the (relatively) save town above ground in which the characters can shop and heal.  Combat in the game is turn-based. Character improvement uses the traditional experience system, but after a level up the guild in Locklaven has to be visited. The game allows for three races (elf, dwarf and human) and four classes (warrior, thief, mage and priest).' FROM games WHERE igdb_id = 12391 ON CONFLICT (game_id, language_code) DO NOTHING;
