INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy!', 'Jeopardy! is a conversion of the long-running TV quiz show where the answers are given and contestants must provide the questions. Compared to the Genesis version released a year earlier, the Game Gear version features only about half the number of questions, and replaces the console version''s photo-realistic style with a more cartoon-like approach.' FROM games WHERE igdb_id = 282483 ON CONFLICT (game_id, language_code) DO NOTHING;
