INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Great Day at the Races', 'A Great Day at the Races is a disc that brings the excitement of horse racing into the home. It contains a series of tutorials covering every aspect of horse racing, from it''s history to a multi-media dictionary of track jargon. It explains both the rudiments of betting and sophisticated handicapping methods. It contains simulated horse races, allowing up to six people to test their handicapping skills on a variety of different race classes. Everything the user needs to learn about the technical and social aspects of the race track is easily accessible.' FROM games WHERE igdb_id = 45946 ON CONFLICT (game_id, language_code) DO NOTHING;
