INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Tennis', 'Power Tennis is a tennis game. It features three modes: singles, doubles, and world tour. Countries featured include Japan, the United States of America, the United Kingdom, Australia, and France. The player can choose between various athletes, and different types of courts (hard, lawn, and clay).' FROM games WHERE igdb_id = 43198 ON CONFLICT (game_id, language_code) DO NOTHING;
