INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Boy', 'Join Magic Boy as he attempts to become a master wizard, and he does this by shooting enemies, putting them in a bag, and throwing them away. He also must get through four areas: Sand Land, Wet World, Plastic Place, and Future Zone. There are also several power-ups that help him on his quest.' FROM games WHERE igdb_id = 12675 ON CONFLICT (game_id, language_code) DO NOTHING;
