INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-slam-dunk', 42452, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zf1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Slam Dunk', 'A basketball game featuring 28 teams. Even though the game doesn''t carry an NBA license, 27 of the teams are based on the cities of their real professional counterparts of that era. The other team is an all star team. The game has an exhibition and playoff mode. Exhibition is the usual team vs team game, while the playoff mode has 8 teams competing to win the championship. Players can choose to turn fouls on or off and also choose how many minutes each quarter will be. The game features a vertical basketball court, with only half of the court shown at any one time. When a player takes the ball from one side of the court to the other, the screen rotates and then the other half of the court is shown. Earvin "Magic" Johnson gives commentary before a game, while broadcaster Chick Hearn gives the play by play during the game.' FROM games WHERE igdb_id = 42452 ON CONFLICT (game_id, language_code) DO NOTHING;
