INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Abbey of Montglane', 'You are one of the leading scholars of XIV century France, who is sent on a special mission by the king and the pope to investigate the Abbey of Montglane. The recent fire damaged the abbey and burned several old manuscripts, you''re tasked to recover ten treasures that couldn''t be accounted for. However things about the abbey are not as they seem to be, the unexplained fire and the strange panic it caused are only the beginning of the mystery lurking inside.' FROM games WHERE igdb_id = 113445 ON CONFLICT (game_id, language_code) DO NOTHING;
