INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ranma 1/2: Byakuran Aika', 'This is the only Ranma game on this platform and was only released in Japan. It features an original story centering on a new character, Arisa Nanjo. After Ranma Saotome''s friends go missing, it is up to him to track them down. The game is a video novel which involves the player, acting as Ranma, selecting from a series of choices, such as what to do or say to someone. The results are then played out in an animated sequence. It uses a Rock-Paper-Scissors-style battle system. The characters are voiced by the original cast from the Anime series.' FROM games WHERE igdb_id = 46402 ON CONFLICT (game_id, language_code) DO NOTHING;
