INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Globdule', 'Globdule, the first ever Splatform game brings an entirely new type of game to the Amiga. Globdule wants to become the latest toy around and has to make his way through a world of caves, evil nasties and cunning traps using his phenomenal sticking abilities on his journey to that great toy shop in the sky. And believe it, with Globdule''s unbelievable Splatform antics, he''s bound to become a star on the Amiga.' FROM games WHERE igdb_id = 13067 ON CONFLICT (game_id, language_code) DO NOTHING;
