INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Dunk Star', 'Super Dunk Star is a basketball game somewhat based on the NBA but with entirely fictional teams. Most of the action is depicted NBA Jam style, with a horizontal view of the court and large sprites for the athletes. Upon scoring a field goal from up close (slam dunks or otherwise), the camera briefly changes to a dynamic shot of the basket. The game was developed by C-Lab and published by Sammy Studios exclusively in Japan.' FROM games WHERE igdb_id = 42270 ON CONFLICT (game_id, language_code) DO NOTHING;
