INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dynamic-stadium', 42278, '1993-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3bgx.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamic Stadium', 'Dynamic Stadium is a baseball game from Eleca/Electronics Application released exclusively for the Super Famicom. While adopting the same behind-the-batter perspective as Namco''s Famista series, Dynamic Stadium presents its athletes as comic book heroes rather than chibi figures, making them absurdly buff and frequently featuring action shots of them catching fly-balls and narrowly making it to base before being caught out. "Safe!" and "Out!" calls are presented as spiky word balloons. Dynamic Stadium does not feature an official NPB license, so all the team names are fictitious. The game was published in Japan by Sammy Corporation and was never localized for overseas territories.' FROM games WHERE igdb_id = 42278 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42278 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
