INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metamorphic Force', 'The Evil King has risen from the dead to rule the world once more. The Greek goddess Athena has summoned the souls of four ancient guardians and bestowed their power upon four heroes to stop the evil once again. These guardians wield the ability to shift into anthropomorphic beasts to fight their enemies.' FROM games WHERE igdb_id = 39385 ON CONFLICT (game_id, language_code) DO NOTHING;
