INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted: The Game Show', 'Similar to the You Don''t Know Jack series of games, Twisted: The Game Show is a trivia challenge game for up to 4 players. The game offers a humorous mix of live character video and computer graphics. After an introduction by the host Twink Fizzdale, you can select your personality by viewing video clips of the various characters egging you on to select them. You advance or retreat through the game board based on your responses to various puzzles, mini-games and trivia questions.' FROM games WHERE igdb_id = 4321 ON CONFLICT (game_id, language_code) DO NOTHING;
