INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Beverly Hillbillies', 'A quasi-adventure based on the movie The Beverly Hillbillies, which in turn was based on the movie of the same name, and not the television show. The player takes control of Jed Clampett after his unexpected discovery of oil, and help him build a new life in Beverly Hills, only to find out that two criminals targeted him as a blackmail victim.' FROM games WHERE igdb_id = 74018 ON CONFLICT (game_id, language_code) DO NOTHING;
