INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunatic-dawn', 66183, '1993-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4o3b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scknhw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunatic Dawn', 'The first title in the Lunatic Dawn series from Artdink, released in 1993 for PC-98 and FM-Towns. The game is dedicated to character creation, RPG-style character development, and exploration. In the beginning, the player creates the playable character, choosing age, gender, and even weaknesses - all of which affect the character''s parameters such as stamina, weapon technique, charisma, etc. Afterwards, the player allocates points into the remaining parameters. The player starts in a city and is absolutely free to go wherever he/she wants. There is a day/night cycle in the game. It is necessary to keep an eye on the character''s stamina and buy food rations - the character can die of exhaustion and hunger. Random enemies appear on the world map and in dungeons. Battle screen is isometric and allows free movement. It is not necessary to choose a command for each turn: the battles evolve automatically until the player interrupts them with a new command.' FROM games WHERE igdb_id = 66183 ON CONFLICT (game_id, language_code) DO NOTHING;
