INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Dinosaur Adventure', '3-D Dinosaur Adventure is an educational game about dinosaurs by Knowledge Adventure. Featuring several mini-games and activities, as well as 3-D images using the included 3-D glasses, this edutainment game is fun for all ages! It should not be confused with Dinosaur Adventure 3-D, also released by Knowledge Adventure in 1999, whose plot revolved around recovering dino-eggs from around Paleo Island.' FROM games WHERE igdb_id = 2294 ON CONFLICT (game_id, language_code) DO NOTHING;
