INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Numan Athletics', 'Numan Athletics is sports game - or more more precisely a bunch of several futuristic sports minigames. The player controls ''numan'' - a superhuman. Four numans (numen?) compete in eight bizarre competitions, such as throwing a rocket, running (faster than a dragster), and shooting targets (with fireballs or missiles). The game supports multi-player for up to four players.' FROM games WHERE igdb_id = 39966 ON CONFLICT (game_id, language_code) DO NOTHING;
