INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smokin-guns-shooting-gallery', 135854, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dgh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc92sw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smokin'' Guns - Shooting Gallery', 'The game represents a shooting gallery with six scenes, each with a different guns and targets: a total of 36 guns and over 100 targets.  The scenes represent:  1) Gangsterland. You as a law defender take on the crime lord and clear the streets of his filth.  2) House on the Hill. You survive through a night at haunted house or become a permanent resident.  3) County Fair. You visit a county fair and try to score as much bounties as possible.  4) Neptune Six. You defend the control room against renegade android raiders.  5) Silicon Gulch. You siege a Wild West town to get rid of bandits.  6) Terminal Flight. You rescue the hostages in airplane full of terrorists.  The events of the game occur on static screen, where you should shoot as much enemies appearing in certain places as possible. Innocent people should not be touched. Time is flown, ammo should be reloaded, and points are gained for successful actions. Top Scores are stored for each scene separately.' FROM games WHERE igdb_id = 135854 ON CONFLICT (game_id, language_code) DO NOTHING;
