INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fly8', 'Fly8 is a single player, wire frame flight simulator that, in the author''s words "puts more emphasis on the dynamics than on the cosmetics". It written in ''C'' and is a reworked and updated version of an earlier program from 1974 that was also called Fly8, that ran on a PDP-15.' FROM games WHERE igdb_id = 141223 ON CONFLICT (game_id, language_code) DO NOTHING;
