INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1993Tris', 'In 1993tris the players goal is to destroy a certain number of flies. Flies drop down into the play field in blocks of 2x2. The flies are colored, and can be killed by matching three or more of the same color together. There are also weapons that will fall down that the player can use by pressing the space bar or enter key.' FROM games WHERE igdb_id = 94288 ON CONFLICT (game_id, language_code) DO NOTHING;
