INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michael Jackson in Scramble Training', 'Michael Jackson in Scramble Training is a Sega AS-1 motion simulator game developed by Sega AM3 and manufactured by Sega. Starring popular musician and Sega collaborator Michael Jackson in the feature role, the game was released in March 1993, and was frequently installed in the company’s flagship arcade venues such as Joypolis and SegaWorld.' FROM games WHERE igdb_id = 233982 ON CONFLICT (game_id, language_code) DO NOTHING;
