INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lawnmower Man', 'The Lawnmower Man is the game based on the 1992 movie of the same name (itself loosely based on a Stephen King short story) starring pre-Bond fame Pierce Brosnan as Dr. Lawrence Angelo, a scientist working for Virtual Space Industries in "Project 5", a secret research that attempts to increase the intelligence of primates using psychotropic drugs and VR training. The twists of the game are true-3D level connectors, based on the CG sequences of the movie, usually all involving avoiding obstacles (and the occasional shooting) at high speed in the VR world. There are four different (Virtual World, Cyber War, Cyber Run and Cyber Tube), each taking a slightly different approach (Virtual World is seen in first person, the objective being dodging obstacles such as trees and archs and reach the exit, Cyber War similar to Virtual World but with some shooting stops, Cyber Run is seen in third person and requires occasional shooting of obstacles, while Cyber Tube is a fast travel with plenty of enemies in a VR tunnel).' FROM games WHERE igdb_id = 5397 ON CONFLICT (game_id, language_code) DO NOTHING;
