INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pangea: Return to Planet Earth', 'Pangea: Return To Planet Earth is sci-fi-pulp/space-opera-themed multiple-choice interactive fiction game presented as an interactive comic book. The game, self-described as adult in nature, is reminiscent of the Heavy Metal film and magazines. The game was programmed in MMGRASP (MultiMedia GRaphic Animation System for Professionals). It was supposed to be the first episode in an ongoing series, but no subsequent episodes appear to have been released' FROM games WHERE igdb_id = 313601 ON CONFLICT (game_id, language_code) DO NOTHING;
