INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider', 'Kamen Rider is a beat ''em up developed by Sun L and published by Bandai for the Super Famicom platform. It is based on the Kamen Rider tokusatsu TV show, specifically the very first incarnation which ran between 1971-1973. The player assumes the role of Takeshi Hongo, the first Kamen Rider, as he fights through the minions and kaijin (human-sized kaiju) of the evil organization Shocker in a series of brawler stages not unlike Final Fight or Double Dragon. The game can also be played co-operatively with a second player who plays as Hayato Ichimoto: the second Kamen Rider. At any time the two players can transform into their Kamen Rider personas, necessary for delivering the final blows on bosses. Kamen Rider was only released on the Super Famicom in Japan.' FROM games WHERE igdb_id = 76063 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 76063 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
