INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duck Hunt', 'Using your 12 GA. Shotgun, sitting in your blind, you''ll have to call in the Ducks. As wave after wave of Ducks come in, you''ll have to blow ''em out of the sky !!! Beautiful 256 Color Graphics, and full Duck flying animation along with realistic hunting sounds ! Many levels of play, and 11 MIDI music files included.' FROM games WHERE igdb_id = 127559 ON CONFLICT (game_id, language_code) DO NOTHING;
