INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super F1 Circus 2', 'Super F1 Circus 2 is a Formula One racing game that allows the player to join any team in the 1993 Formula One season and take part on sixteen different circuits all over the world. They can also configure the load-out for the F1 vehicle. It is the second official F1 Circus game for the system, though technically the third due to 1992''s Super F1 Circus Limited. Overall it is the eighth F1 Circus game.' FROM games WHERE igdb_id = 42268 ON CONFLICT (game_id, language_code) DO NOTHING;
