INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncle Clyde''s Consonant Slides', 'Uncle Clyde''s Consonant Slides is a single-player game to help children learn consonant sounds. The player chooses from 3 lists of different consonant sounds, and there are four different question types. The player receives animated quizzes where they try to correctly identify the missing consonant starting a word.' FROM games WHERE igdb_id = 285868 ON CONFLICT (game_id, language_code) DO NOTHING;
