INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stellar-Fire', 'The dreaded Draxon race has been at it again, pushing the human race around, working to either enslave all 10 billion humans or wipe them out completely. As the last surviving pilot sent on a mission to thwart the Draxons'' plans, all hope rests on you. Invade each of the fortified moons orbiting the Draxons'' homeworld of Arctaurus and then aim for the mother planet itself.' FROM games WHERE igdb_id = 14515 ON CONFLICT (game_id, language_code) DO NOTHING;
