INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crime-fighter', 50353, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2urp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc94ep.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Fighter', 'In contrast to many other games and unlike the name of the game announces, you don''t fight against crimes, but you try to commit as many of them as possible. For example you can play pickpocket, raid supermarkets and hotels, steal cars, raid banks, attack mail trains, and so on. Since you are in a big town you have many different opportunities for this. As soon as you have a high standing in the criminal underworld, you are also able to sign on gangsters that join your gang. This gangsters then can be trained or equipped with weapons (for example with pistols or machine guns). Your aim is to seize the power in the underworld. But the way is very dangerous, especially since the other players try exactly the same. And also the police are hard on your heels....' FROM games WHERE igdb_id = 50353 ON CONFLICT (game_id, language_code) DO NOTHING;
