INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albert Odyssey', 'Albert Odyssey is a tactical role-playing video game. The game features strategy-based combat in addition to traditional role-playing game elements in two-dimensional environments. It is the first game in the Albert Odyssey series, and was followed by two sequels, Albert Odyssey 2: Jashin no Taidou and Albert Odyssey: Legend of Eldean.' FROM games WHERE igdb_id = 15889 ON CONFLICT (game_id, language_code) DO NOTHING;
