INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Richard Scarry''s Busytown', 'This early version is different from its PC counterpart with this version featuring six different stages to choose from and each with their own type of gameplay. Additionally, the player can choose these different locations at the main screen that has the player become Lowly Worm and fly around the map using his Apple Helicopter. It also features many characters from Scarry''s children''s books.' FROM games WHERE igdb_id = 46202 ON CONFLICT (game_id, language_code) DO NOTHING;
