INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Willy', 'Little Willy''s mother & sister were kidnapped while on a family trip to Earth II.  Help him save them in this EGA platformer while solving the puzzles, avoiding hazards, and blasting off enemies.  Visually and gameplay-wise, Little Willy resembles the Crystal Caves & Secret Agent games that were published by Apogee Software.' FROM games WHERE igdb_id = 139047 ON CONFLICT (game_id, language_code) DO NOTHING;
