INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Huckleberry Hound in Hollywood Capers', 'Huckleberry Hound''s latest movie epic has won a glittering array of Oscars at the recent award ceremony. Unfortunately, they have been stolen along with a collection of fake diamonds by that mischievous chimp, Wee Willy, who has then scattered them all around Cartoon World. Huck now has the task of tracking down all the diamonds as well as the Oscars. He knows that the diamonds are needed in his next film, so he must find every single one before he can prepare for his next blockbuster.' FROM games WHERE igdb_id = 73530 ON CONFLICT (game_id, language_code) DO NOTHING;
