INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepper''s Adventures in Time', 'This point n'' click adventure game is actually an edutainment (entertainment leading to education) title developed by Sierra, who were also responsible for other games such as the Eco quest and Dr. Brain series. The object of this game is to help a little girl called Pepper, solve puzzles based on history and logic, so that she can fix the mess caused by Dr. Fred''s time machine. At certain points in the game, the player is even allowed to control her pet dog, Lockjaw.' FROM games WHERE igdb_id = 50897 ON CONFLICT (game_id, language_code) DO NOTHING;
