INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yokoyama Mitsuteru Sangokushi II', 'Yokoyama Mitsuteru Sangokushi II ("Mitsuteru Yokoyama''s Romance of the Three Kingdoms II") is a strategy game and the sequel to the original Yokoyama Mitsuteru Sangokushi. Both games were adapted from the eponymous manga artist''s graphic novel adaptation of the ancient Chinese novel. Specifically, they were based on an anime adaptation of the manga, released close to the same time.' FROM games WHERE igdb_id = 60947 ON CONFLICT (game_id, language_code) DO NOTHING;
