INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rules of Engagement 2', 'In Rules of Engagement 2, you are the Fleet Commander of the Federated Worlds Armed Forces (FWAF) main task force. The war with the United Democratic Planets (UDP) has escalated, and hostile alien spacecraft have been discovered in the Local Group. In charge of a fleet of starships, you must engage enemy vessels and hostile outposts in order to protect the Federated Worlds.' FROM games WHERE igdb_id = 14420 ON CONFLICT (game_id, language_code) DO NOTHING;
