INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-factor', 62298, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru1m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Factor', 'Power Factor is a 1993 side-scrolling action-platform video game developed by Hand Made Software and published by Atari Corporation in North America and Europe exclusively for the Atari Lynx. Based around a video game within a video game concept, players take control of a character who is in turn playing on a virtual reality simulator assuming the role of Redd Ace, which is recreating his battle against the Sinlendo Techmods by recovering necessary bomb components to defeat the alien race at the Ceegraian Power Station. Its gameplay consists of platforming, exploration and weapons-based combat with a main four-button configuration. Power Factor originally began as a project intended for the Atari ST that was in development by Red Rat Software under the title Red Ace, which was nearly completed before being left unpublished due to internal issues at the company and its eventual disbandment prior to release, however Hand Made Software would later develop a conversion to the Lynx. Power Factor has been met with positive reception from critics and reviewers since its initial release, who praised various aspects of the title such as the unique storyline, graphics and character animation but many felt divided in regards to the sound design and gameplay. In 2005, a ROM image of the original ST version was leaked online.' FROM games WHERE igdb_id = 62298 ON CONFLICT (game_id, language_code) DO NOTHING;
