INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park', 'Jurassic Park is a top-down action-adventure game based on the blockbuster film. Players take on the role of Dr. Alan Grant, exploring the island, rescuing stranded workers, and battling escaped dinosaurs. The game features maze-like levels, limited ammo, and key-based progression, combining exploration and survival in a challenging prehistoric setting.' FROM games WHERE igdb_id = 25880 ON CONFLICT (game_id, language_code) DO NOTHING;
