INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eagle Eye Mysteries', 'Eagle Eye Mysteries is a educational game that has you play along side one of the two in-game protagonists Jake or Jennifer Eagle. Aid these Twin kids form Eagle Eye Detective Agency and help and explore their community of Richview by solving the cases given to them.' FROM games WHERE igdb_id = 70962 ON CONFLICT (game_id, language_code) DO NOTHING;
