INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whale''s Voyage', 'Whale''s Voyage is a sci-fi role-playing game with trading elements. The story involves a space traveler who has made a bad deal buying a space ship known as Whale, which turned out to be half-wrecked. Stranded on the orbit of a remote planet, the traveler and his crew have to find a way to gain money and outfit the ship so that it will stand a chance in that dangerous area.' FROM games WHERE igdb_id = 2522 ON CONFLICT (game_id, language_code) DO NOTHING;
