INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayon Shin-Chan: Ora to Poi Poi', 'The game is a simple card game with a Tetris element. The layout is similar to a Tennis court with both players on either sides defending their goal, while stacks of cards are positioned in the center. Players must move Shin up and down sliding cards, in two''s, to the center pile matching up symbols and push each stack back to the opponent''s side in an attempt to over take their goal.' FROM games WHERE igdb_id = 48533 ON CONFLICT (game_id, language_code) DO NOTHING;
