INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-masons-dinosaurs-for-hire', 46252, '1993-07-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zdw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5jqd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Mason''s Dinosaurs for Hire', 'Unknown monsters and weird robotic creatures attack the Earth. For some reason, the only ones who can stop the invasion are the three Dinosaurs for Hire: Archie, a tyrannosaurus rex and their leader; the triceratops Lorenzo, lover of fine food, fine wine, and fine clothes, and the one-eyed, unpredictable stegosaurus Reese. Each dino has its own strengths and weaknesses. You guide the dinosaur of your choice through the platform levels of the game. You are equipped with a gun: tons of enemies will attack you from all the sides, so your best bet will be walking with the fire button pressed down. You can shoot to all the directions and also engage in melee combat when the enemy is too close. Each level has a boss enemy waiting for you in the end. There is also a cooperative two-player mode.' FROM games WHERE igdb_id = 46252 ON CONFLICT (game_id, language_code) DO NOTHING;
