INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prime Mover', 'The smoothest, most realistic arcade motorcycle game ever hits the Amiga with the arrival of Prime Mover. Featuring 5 awesome bikes, a huge selection of the most challenging tracks from around the world and realistic and testing riding conditions, Prime Mover screams onto the grid and into pole position ahead of all the competition. So if you want to sample the power and sheer excitement of the international bike racing circuit, then Prime Mover is the clear winner.' FROM games WHERE igdb_id = 12722 ON CONFLICT (game_id, language_code) DO NOTHING;
