INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bulls-versus-blazers-and-the-nba-playoffs', 46284, '1993-03-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5k2v.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bulls Versus Blazers and the NBA Playoffs', 'Another update in Electronic Arts'' basketball series, this time featuring the teams and players from the 1992 NBA playoffs plus the East and West All-Stars. Features unchanged from the previous games include detailed stats, instant replay, substitutions, free throw T-meter and signature moves, some of which are new. Exclusive to the Genesis version is the ability to create your own All-Star teams and to call defensive plays.' FROM games WHERE igdb_id = 46284 ON CONFLICT (game_id, language_code) DO NOTHING;
