INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Eichhof', 'The Last Eichhof is a vertically scrolling shooter released in 1993 for DOS. In this game, the player controls a beer bottle and destroys bottles, beer glasses, cans, and other beer-related items. The game''s name refers to a small independent Swiss brewery "Brauerei Eichhof". Since the game''s code is in the public domain, it was later ported to Windows and Linux.' FROM games WHERE igdb_id = 69640 ON CONFLICT (game_id, language_code) DO NOTHING;
