INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Air Zonk: Rockabilly-Paradise', 'Zonk is back in Super Air Zonk, the sequel to the shooting game spin-off of the Bonk series, Air "Zonk." Now moving to a rockabilly beat and able to transform into nine different characters, Zonk lets loose through seven action-packed stages in another battle against his arch nemesis, SandroVitch. Power up Zonk with the classic Meat item, eventually turning him into the champion of justice, Ultra Zonk, or the fearsome Tyrano Zonk in the latter stages of the game.' FROM games WHERE igdb_id = 73031 ON CONFLICT (game_id, language_code) DO NOTHING;
