INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nobby the Aardvark', 'Nobby the Aardvark is a platform game. The player takes the role of Nobby, an aardvark who is hungry for ants. The game''s plot involves Nobby trying to get to Antopia, a place where there are ants everywhere, so Nobby can eat his belly full.' FROM games WHERE igdb_id = 125181 ON CONFLICT (game_id, language_code) DO NOTHING;
