INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('warlocks', 37096, '1993-11-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ckineagv8qrhzjdtf6wf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warlocks', 'A platform shoot-em-up featuring a reincarnated knight who was tasked with freeing the world of Lylvania from the tyranny of 3 demented Warlocks. The game set over ten large levels. The early levels are reasonably linear, but they soon become larger, requiring much exploration. Hidden rooms and caves can be found, containing extra lives, magical power-ups and level warps. Other features of this game are smooth parallax scrolling, thunder and lightning, rain, animating backdrops, stunning 256 colour graphics and great sound effects and music.  This game has been reviewed in:  Acorn Computing, Christmas Special December 1993 (with coverdisc demo)  Archimedes World, January 1994  Acorn User, February 1994  Acorn Action, Spring 1994  The game requires 1Mb of ram and RiscOS 2 or higher, but as it uses some minor video trickery, it will not work properly on VIDC2 machines without a software VIDC patch. It is compatible with the standard Acorn joysticks.  To enter the first hidden room, on level one after the second drop, walk left as far as you can and through the wall. This room continues past the water-fall, where you must stand on a chest and jump into the wall next to it to gain access to the third hidden part. When climbing the ladder out of the hidden room, walk into the far archway to be transported to the next level.  Many other hidden rooms are spread throughout the levels.  The levels are:  1 - The Forest  2 - The Graveyard  3 - The Waterfall  4 - The First Encounter  5 - The Giant Forest  6 - The Caves  7 - Skull Island  8 - The Volcano  9 - The Second Encounter  10 - The Castle' FROM games WHERE igdb_id = 37096 ON CONFLICT (game_id, language_code) DO NOTHING;
