INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tnn-bass-tournament-of-champions', 46592, '1993-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ukmivahwddrm8z3ogd2n.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TNN Bass Tournament of Champions', 'Starting at 7.30 in the morning, the player has until 4PM to take a boat on the lake and fish for bass to beat competitors. The boat can be steered freely using a top-down view until an appropriate spot has been found by checking the lowrance monitor. The game then switches to a first-person view, also showing the fisher from a side-view on a separate part of the screen, and it is possible to look around in the environment. Casting is done using a power meter to determine the distance. As the bait sinks, a monitor can be checked for nearby fish. There are also visual clues through splashing water. The player can check the depth and reel in when needed. When a fish has been caught, it becomes a sensitive play with the line tension to make sure it does not snap shown through the side-view of the fisher. At the end of the day the boat can go back to the weighing area to determine the results. Money earned in the tournaments can be used to acquire new spin reels, bait reels, boats, lines and lures.' FROM games WHERE igdb_id = 46592 ON CONFLICT (game_id, language_code) DO NOTHING;
