INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bio-Morph Encyclopedia', 'Though he was accused of being a murderer, the English 19th century photographer Edward Muybridge kept taking still photographs of man and animals in motion. The interactive CD-ROM “Bio-Morph Encyclopedia” by Nobuhiro Shibayama is based on plates of his photographs, but shows them from a different perspective.' FROM games WHERE igdb_id = 274060 ON CONFLICT (game_id, language_code) DO NOTHING;
