INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theatre of Death', 'Theatre of Death is an isometric tactical war game.. You are a commander of squads of soldiers, which you have to guide through missions in various terrains from the grasslands, desert and snow to the Moon, using a variety of weaponry at your disposal such as pistols, machine guns, grenades, rocket launchers, landmines, and even tanks, APCs and choppers.' FROM games WHERE igdb_id = 15483 ON CONFLICT (game_id, language_code) DO NOTHING;
