INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sub Terrania', 'The game consists of 10 missions. Each mission takes place in a vast cavern, with interesting weather conditions. You must explore it and complete the mission objectives -- usually collecting sub parts, rescuing trapped miners, or destroying giant, epic bosses. You can also explore the levels, but keep an eye on your fuel gauge and beware the many hazards!' FROM games WHERE igdb_id = 22680 ON CONFLICT (game_id, language_code) DO NOTHING;
