INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Helious II', 'The second half of Helious. The graphics and overall design are the same as the first game; this game just adds more levels. Originally, the first part was available without charge as a shareware "teaser", and you had to pay for this second part, Helious II.' FROM games WHERE igdb_id = 18635 ON CONFLICT (game_id, language_code) DO NOTHING;
