INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash ''n Burn', 'In Crash ''n Burn, players assume the role of any one of six cyberpunks, each equipped with a unique car and a deadly supply of weapons. Full-motion videos of the racers are accessible in between races, in which each character flaunt their skills and insult their opponents with death threats. The game has rally and tournament modes with a total of 30 tracks designed for one player.' FROM games WHERE igdb_id = 95438 ON CONFLICT (game_id, language_code) DO NOTHING;
