INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doppyun Donpisha', 'Hero is an aspiring photograph to cover women photo sessions. But he actually is tired of those neat photos and wants to shoot usual girls outdoors in their natural environment and without being caught by the police. He looks up to a colleague who agrees to accept the hero as his apprentice if he made nude photos of a list of girls.' FROM games WHERE igdb_id = 230224 ON CONFLICT (game_id, language_code) DO NOTHING;
