INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyna Brothers 2', 'Dyna Brothers 2 (ダイナブラザース２) is the sequel to Dyna Brothers, and is a Sega Mega Drive simulation game released exclusively in Japan. CRI also released an expanded version on the Japanese Sega Channel, Dyna Brothers 2: Sega Channel Special (ダイナブラザーズ２スペシャル). This version has since been rereleased on the Japanese Virtual Console, from which the ROM comes from. Whether or not there was a North American release as such is unknown.' FROM games WHERE igdb_id = 4547 ON CONFLICT (game_id, language_code) DO NOTHING;
