INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4-in-1 Funpak Volume II', 'Now get four times the fun from your Gameboy system with 4-in-1 Funpak, Vol. II. If you like Yahtzee, you''ll love Yacht. Cut the cards for hours of fun with Solitaire. Peg your spot in the winner''s circle with Cribbage. Or build on your skills with Dominoes. You can take these all-time favorite games with you anywhere, anytime. It''s like having cards, dic and dominoes in the palm of your hand. So come on, get ready to shake, shuffle, and roll your way to hours of fun!' FROM games WHERE igdb_id = 93553 ON CONFLICT (game_id, language_code) DO NOTHING;
