INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martial Champion', 'Martial Champion is a versus fighting game similar in concept to Street Fighter II. There are ten characters to choose from, each representing his or her own country. The main protagonist is a Japanese martial artist named Jin; others include his countryman Zen, a kabuki fighter; a Chinese kung-fu expert and a vampire from Hong-Kong; an Egyptian princess; a scimitar fighter from Saudi Arabia; a spear-wielding Kenyan warrior; a French weapons specialist; and two North Americans - an eyepatched soldier and a blonde female ninja-like fighter.' FROM games WHERE igdb_id = 39544 ON CONFLICT (game_id, language_code) DO NOTHING;
