INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EcoQuest II: Lost Secret of the Rainforest', 'In the wake of the tremendous success of the original EcoQuest: The Search for Cetus, Sierra has decided to follow up with a sequel. In EcoQuest 2: Lost Secret of the Rainforest, you play the role of Adam Greene who, along with his father Noah - doctor of ecology, arrives in a country in the middle of the rainforest in order to make some ecological studies. After having separated from his father, Adam must venture into the rainforest, discover the secret of the mysterious Forest Heart and find the lost City of Gold in his pursuit of a remedy for the Grove People.' FROM games WHERE igdb_id = 7694 ON CONFLICT (game_id, language_code) DO NOTHING;
