INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dai-3-ji Super Robot Taisen', 'Dai-3-ji Super Robot Taisen ("3rd Super Robot Wars") is the third game in Banpresto''s immense Super Robot Wars/Taisen series.Six months after the DC War (as chronicled in Super Robot Wars 2), the DC seems to be regaining their former combat strength thanks to the Zabi family. In response, the United Nations has decided to reorganize itself into the Earth Federation.' FROM games WHERE igdb_id = 42564 ON CONFLICT (game_id, language_code) DO NOTHING;
