INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakunetsu Pro Yakyuu ''94 Ganba League 3', 'Hakunetsu Pro Yakyuu ''94 Ganba League 3 is the third and final Super Famicom baseball game from Sting Entertainment and Epic/Sony Records. Like its two predecessors, the game adopts a super-deformed cartoon style. Hakunetsu Pro Yakyuu ''94 Ganba League 3 follows Hakunetsu Pro Yakyuu Ganba League (best known in the US as Extra Innings) and Hakunetsu Pro Yakyuu Ganba League ''93.' FROM games WHERE igdb_id = 38173 ON CONFLICT (game_id, language_code) DO NOTHING;
