INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Core', 'An underwater nuclear research base has been invaded by a hostile craft. Captain Dawnrazer is sent in to wipe up the aliens and other beings, and that''s where you come in. Deep Core is a dark platform adventure with similarities to Gods. There are nine main levels, each of which is split into sub-levels and also has bonus sections leading off from it. Each of the 6 weapons which are on offer can be boosted in power.' FROM games WHERE igdb_id = 12568 ON CONFLICT (game_id, language_code) DO NOTHING;
