INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choujikuu Yousai Macross: Scrambled Valkyrie', 'Choujikuu Yousai Macross: Scrambled Valkyrie is a 2D side-scrolling science fiction shooter. Aside from Hikaru, the player can also choose to play as Max or Milia. Each character has different types of power, range and weapon effect per VF-1 mode (Fighter, Gerwalk and Battroid). Power-ups obtained will increase weapon range and potency for up to three levels each.' FROM games WHERE igdb_id = 42537 ON CONFLICT (game_id, language_code) DO NOTHING;
