INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rolling Thunder 3', 'The events in the third game in the series are synchronous with RT2. At the end of the twentieth century, satellites around the globe are being shot down, disrupting communications. Secret agency Rolling Thunder discovers the organization behind the terror: Geldra. While agents Leila and Albatross are fighting the leader Gimdo (RT2), agent Jay is instructed to bring down Dread, the second-in-command.' FROM games WHERE igdb_id = 46243 ON CONFLICT (game_id, language_code) DO NOTHING;
