INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kevin Keegan''s Player Manager', 'Kevin Keegan''s Player Manager combines a football management sim with the Kick Off football game. The Kick Off game includes several skill levels, Challenge Cup and practice options. Manager offers three management skill levels, three division league and two Cup competitions. Options to play on the pitch or watch and get computer predicted results.' FROM games WHERE igdb_id = 42618 ON CONFLICT (game_id, language_code) DO NOTHING;
