INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-Rank Thunder Tanjouhen', 'A-Rank Thunder Tanjouhen (Aランクサンダー 誕生編?) is a adventure game released in 1993 on Mega-CD. The game was developed by Riot and released by Telenet. The game''s cover art was created by Yasushi Nirasawa, in his position as a model-builder for Hobby Japan magazine.' FROM games WHERE igdb_id = 5355 ON CONFLICT (game_id, language_code) DO NOTHING;
