INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocky-rodent', 42648, '1993-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z9m.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocky Rodent', 'Mafia member Don Garcia has kidnapped Melody, the daughter of the owner of the Rose Restaurant. Rocky Rodent agrees to rescue her in exchange for an all-you-can-eat meal. In order to find Melody, Rocky Rodent has to complete a number of fast-paced, side-scrolling platformer levels. While he can also defeat enemies by jumping on them, his most important weapons are four different hairstyles: His first hairstyle allows him to skewer and throw his enemies, destroy porous blocks as well as cling to and jump up certain ledges. A mohawk can be thrown at enemies like a boomerang or thrown into certain walls, from where it serves as a trampoline. Braids can be used as a grappling hook and a corkscrew-like haircut lets him bounce on his head to jump higher than normal. When Rocky is attacked by an enemy, he looses his current haircut. If he is attacked while not wearing any special haircut, he looses a live.' FROM games WHERE igdb_id = 42648 ON CONFLICT (game_id, language_code) DO NOTHING;
