INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morph', 'A young boy is trapped in molecular limbo. He needs your help to return to his human form. Morris Rolph (Morph to his friends) has his life transformed when his uncle''s experimental teleport machine goes horribly wrong! Trapped in a world of twinkling atoms, Morph can morph into four different physical states. You must guide his perilous journey back to the teleport machine.' FROM games WHERE igdb_id = 13053 ON CONFLICT (game_id, language_code) DO NOTHING;
