INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Equinox', 'Equinox is the sequel to Solstice. It is presented in a 3D isometric view with colourful graphics. The game is based upon solving puzzles to progress to the next dungeon. In the game you play the son of the hero in the first game, Shadax. Shadax has been kidnapped by an evil witch and it is up to you to rescue him.' FROM games WHERE igdb_id = 100180 ON CONFLICT (game_id, language_code) DO NOTHING;
