INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Golf Classics: Wicked 18', 'Wicked 18 is a golf game with a twist. The player takes control of a golfer on the most extreme 18 holes of golf with tall mountains, canyons and various objects and obstacles ready to stop the player at any time. There are four different game modes to choose from: Stroke, Match, Skin and Tournament with the ability to play against three other friends in a heated match. There is also a battery back-up that saves the players progress after each hole is completed.' FROM games WHERE igdb_id = 38401 ON CONFLICT (game_id, language_code) DO NOTHING;
