INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Journeyman Project', 'The year is 2318. As Agent #5 of the Temporal Security Agency, you must safeguard history from sabotage. Explore photorealistic 3D worlds of the past and future, solve mind-bending puzzles, and outwit menacing robots in a struggle to undo the acts of a saboteur bent on altering the past.' FROM games WHERE igdb_id = 9517 ON CONFLICT (game_id, language_code) DO NOTHING;
