INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park', 'One of many games based on the 1993 blockbuster Jurassic Park, the version for Sega''s 8-bit systems combines side-scrolling shooting action and platforming levels. In each of the five stages of the game, one escaped dinosaur species must be recaptured. Each level begins with a side-scrolling driving section. Dinosaurs attack the car and must be fended off by firing at them with a crosshair. If the player survives long enough, a boss battle against an especially powerful dinosaur follows.' FROM games WHERE igdb_id = 134299 ON CONFLICT (game_id, language_code) DO NOTHING;
