INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Team: Kid''s Typing', 'Spooky, a talkative ghost who lives in the attic of an all-American home, uses humor and games to teach kids how to type. Built-in intelligence enables him to continuously create new lessons based on your child''s typing accuracy and speed. Starting with simple lessons that teach the location of the keys, your child will advance through exercises and games that challenge problem areas. Printable reports allow you to track progress.' FROM games WHERE igdb_id = 151846 ON CONFLICT (game_id, language_code) DO NOTHING;
