INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe Montana''s NFL Football', 'This enhanced version of the Joe Montana series features 3D models and even full-motion video of Joe Montana himself. It sports a full NFL license with all 28 teams of the time with their respective nicknames and logos, along with 10 of the all-time greatest Super Bowl teams including ''85 Bears, the ''72 Dolphins, just to name a few, that the player can compete against if they win the biggest game of the year.' FROM games WHERE igdb_id = 46419 ON CONFLICT (game_id, language_code) DO NOTHING;
