INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cadillacs and Dinosaurs', 'Cadillacs and Dinosaurs is a side-scrolling, beat ''em up arcade game based on the comic book series Xenozoic Tales. In the game, the player has access to several attacks. Each character has two special moves including one that depletes a character''s health upon contact with an enemy and when two or more players play together, they can trigger a team-attack. Players can also find and use various firearms, throwing weapons such as rocks and explosives, and melee weapons such as clubs.' FROM games WHERE igdb_id = 5368 ON CONFLICT (game_id, language_code) DO NOTHING;
