INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outback Joey', 'Outback Joey is a fitness focused platform game, specifically designed for the Sega Genesis'' HeartBeat Catalyst accessory. Joey, the main character, navigates through four distinct levels. He utilizes his jumping ability to combat enemies with kicks and dodge obstacles. At specific points within the game, Joey has the opportunity to obtain boxing gloves, enhancing his ability to vanquish foes.' FROM games WHERE igdb_id = 281554 ON CONFLICT (game_id, language_code) DO NOTHING;
