INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puggsy', 'Puggsy is no ordinary game. Using the unique system of Total Object Interaction (TOI), you have to guide Puggsy through some of the best puzzles and most frantic arcade action ever seen in his quest to retrieve his stolen spaceship. Incorporating graphic techniques never seen before, fantastic gameplay plus a complete Junior section for the younger player. Puggsy is destined to become the next world-wide smash hit.' FROM games WHERE igdb_id = 5425 ON CONFLICT (game_id, language_code) DO NOTHING;
