INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Soccer', 'A soccer simulation game which takes place in your preference of side, top or 3/4 overhead view. The game dynamically zooms in and out at certain points of the game like a long goal kick. The mode of play are pre-season, custom teams, continental cup, nations shield, custom trophy and practice. Options to change the match length, weather and game speed are available.' FROM games WHERE igdb_id = 46005 ON CONFLICT (game_id, language_code) DO NOTHING;
