INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battleship-the-classic-naval-warfare-game', 46437, '1993-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dn1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmj1g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battleship: The Classic Naval Warfare Game', 'Battleship is an NES, Sega Game Gear and Game Boy video game based on the board game of the same name. Do you have what it takes to command your own fleet of six ships? Can you survive thrilling, ruthless combat on the high seas? Stalk your enemy through unfriendly waters. Secretly plot your plan of attack. Then fire. It''s a hit! But remain on red alert! For your opponent wants victory as much as you do! Capsize a carrier. Demolish a destroyer. Sink up to six ships in your opponent''s fleet before your own vessels are found and sunk. Blast the torpedoes and full speed ahead!' FROM games WHERE igdb_id = 46437 ON CONFLICT (game_id, language_code) DO NOTHING;
