INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jantei-monogatari-3-saver-angels', 321173, '1993-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zxf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scucjc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jantei Monogatari 3: Saver Angels', 'The events of Saver Angels take place after those described in the previous installment of the series, when peace on Earth has already been restored thanks to the efforts of Divan and Marie. Three cosmic spirits have lost their way in space and have to descend onto Earth, taking corporeal form. They enter the bodies of three young women who died recently: one in a traffic accident, another from disease, and the third one - a ten-year-old girl - after committing suicide. All three were avid mahjong players, and all three are now revived and endowed with mysterious mahjong powers. A special Mahjong Academy opens, and the Saver Angels (as the group begins calling itself) is ready to defeat any aliens and demons in that ancient Chinese game. Saver Angels restores adventure elements that were absent from the previous game, and even enhances them. The player is now able to move in first-person perspective by pointing and clicking on a spot on the screen. Exploring locations, the player triggers scenes, which in turn lead to mahjong games. A special "mahjong mode" allows the player to choose an opponent from the story mode and challenge her (or him) to a mahjong match right away.' FROM games WHERE igdb_id = 321173 ON CONFLICT (game_id, language_code) DO NOTHING;
