INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Fútbol', 'As in Simulador Profesional de Fútbol, here you have the option of taking full control (buying players, contracting publicity, deciding the tickets price, etc) of any of the teams that participated in the Spanish Primera División, this time focusing on the 1993/94 season. Matches would be addressed in a similar way too, you will either play the game yourself, watch it or just see the final result.' FROM games WHERE igdb_id = 144013 ON CONFLICT (game_id, language_code) DO NOTHING;
