INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooter''s Magic Castle', 'Scooter’s Magic Castle is an education game where you control Scooter, and by clicking on various items in the Castle you can interact with them, often starting a small mini-game. The activities available around the castle are numerous, ranging from simple memory tests to composing your own melody. During his travels around the castle’s corridors, Scooter is assisted by a helpful owl, who acts as the game’s options menu and can also teleport you to any chamber.' FROM games WHERE igdb_id = 72173 ON CONFLICT (game_id, language_code) DO NOTHING;
