INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-chinese-world-2-uchuu-ichi-butou-taikai', 37840, '1993-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zec.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Chinese World 2: Uchuu Ichi Butou Taikai', 'Super Chinese World 2: Uchuu Ichi Butou Taikai is a Japanese-only action RPG developed by Culture Brain. It is the second SNES Super Chinese game, being a sequel to Super Ninja Boy which was released in North America. Contrary to its predecessor, it doesn''t feature any traditional turn-based battles anymore, but a couple of platforming sections still remain. Jack and Ryu are now travelling between different planets to defeat some alien invaders, who kidnapped the world leaders. The battle system was also greatly improved. Jack and Ryu now have a lot of new attacks and even a few different skills (although they still share levels and items), they can turn into giant ninjas in order to cast the most advanced spells and it is possible to use weapons or spells without going to the menu. A fighting mode has also been added, allowing to play with many other characters than the heroes.' FROM games WHERE igdb_id = 37840 ON CONFLICT (game_id, language_code) DO NOTHING;
