INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ruin-kami-no-isan', 59325, '1993-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8nv1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckavu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruin: Kami no Isan', 'Ruin: Kami no Isan is an action RPG. The player navigates Jan through top-down towns and hostile areas; the "world map" is not free-roaming, allowing only linear advancement from location to location. Hostile areas are populated by enemies who are visibly walking on screen. Unlike most Japanese RPGs, there are no separate "battle screens" in the game; the monsters are fought on the same spot they are encountered on, like in action games. However, unlike most action RPGs, there is a party in Ruin. The player controls only Jan, while the other party members act according to AI routines: attacking, casting offensive and healing spells, etc. The rest of the gameplay is traditional Japanese RPG style: acquiring better weapons and armor, automatic leveling up, linear story development, etc.' FROM games WHERE igdb_id = 59325 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 59325 AND p.igdb_id = 150 ON CONFLICT DO NOTHING;
