INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-eye-2', 308247, '1993-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hyk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct0a3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Eye 2', 'Metal Eye 2 is set in the same sci-fi universe and is closely related story-wise to the first game. In the future, people have built the floating city Zeron, where the best scientists work on creating androids, artificial human beings who look the same way as real ones. Harvest Corporation is the biggest company that creates androids. The hero of the game is a scientist named Wirg, the father of the first game''s protagonist. His work is to train the androids after they have been created. One day, the company building is attacked, and Wirg has to escape. He is saved by a nun and brought into a small town in the middle of wasteland, where his adventure begins. The game mostly follows a traditional Japanese RPG template: Wirg and his companions (a party of three) explore the top-down world and fight random enemies in turn-based combat in first-person view. The pictures of enemies appear super-imposed on whatever location the characters are currently in, without separate battle screens. The towns have isometric perspective. Like its predecessor, the game has a large world map that consists of many separate screens, often including dungeon-like locations.' FROM games WHERE igdb_id = 308247 ON CONFLICT (game_id, language_code) DO NOTHING;
