INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Spacehead', 'Cosmic needs your help! He has no money, no car, and no respect from his fellow Cosmonaut''s! The trouble is, no one believed his tale of discovering a far away planet called "Earth" so it''s your job to help him get back there and take some handy snaps! Starting from his home town Old Lino Town, it''s Cosmic gameplay all the way in a unique blend of adventure and arcade action plus a whole galaxy of surprises thrown in!' FROM games WHERE igdb_id = 12013 ON CONFLICT (game_id, language_code) DO NOTHING;
