INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aa-megami-sama--2', 230013, '1993-03-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5y2g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckekv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aa! Megami-sama!', 'Based on the anime series Ah! My Goddess, the game follows the story of a Japanese high-school student named Keiichi, who has accidentally summoned the powerful, yet very lovely Norse goddess Verdandi (mercilessly misspelled Belldandy in the game) and pronounced a wish to stay with her forever. Now the gorgeous goddess has become a part of his life, and the two find themselves involved in constant misunderstandings and comical situations, yet also develop feelings for each other...' FROM games WHERE igdb_id = 230013 ON CONFLICT (game_id, language_code) DO NOTHING;
