INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Muscle Bomber Duo: Ultimate Team Battle', 'Muscle Bomber Duo: Ultimate Team Battle, released in Japan as Muscle Bomber Duo: Heat Up Warriors, is an updated version of the original Slam Masters which eliminates the Single Match mode from the original game, focusing solely on the two-on-two Team Battle mode. The same character can now be chosen by more than one player and each wrestler now has two additional special moves: a dual side attack and a vacuum move. Duo is the only game in the series to retain the Muscle Bomber title for its international releases.' FROM games WHERE igdb_id = 39317 ON CONFLICT (game_id, language_code) DO NOTHING;
