INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince of Persia 2: The Shadow and the Flame', 'Prince of Persia 2: The Shadow and the Flame is a platform game released as the sequel to 1989''s Prince of Persia. Prince of Persia 2 was published for MS-DOS and ported to Macintosh, Super NES, and FM Towns – a much shorter list of platforms than the first game. It was also available as a bonus that unlocks in the Xbox NTSC version of Prince of Persia: The Sands of Time.' FROM games WHERE igdb_id = 3164 ON CONFLICT (game_id, language_code) DO NOTHING;
