INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battleship', 'Battleship is a 1993 video game based on the board game of the same name. The object is to sink the opponent''s entire fleet without them sinking the player''s fleet first. In this updated version, both the player and the computer get extra firepower from military aircraft and support weapons. There are even scenarios that start a player off in a pre-played game that he must resume (and overcome a bleak scenario).' FROM games WHERE igdb_id = 220787 ON CONFLICT (game_id, language_code) DO NOTHING;
