INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dave Goes Nutz!', 'Life is difficult enough without having Dr. Nemesis as your arch-villain. Why does he have to pick on Dave’s little brother, Delbert, so much? Not only does he snatch the already kidnapping-prone Delbert, but he hides him away deep in the bowel of an insane asylum! Crazy nurses wearing purple of all colors wander the halls, cleaver wielding orderlies, and jolts of electricity all stand in Dangerous Dave’s way in Dave Goez Nutz!' FROM games WHERE igdb_id = 11389 ON CONFLICT (game_id, language_code) DO NOTHING;
