INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA', 'The player is put behind the wheel of a stock car (known as the Hornet), with the choice of three tracks as well as an automatic or manual transmission. The player''s objectives are to outrun the competing cars, and complete the race before time runs out.' FROM games WHERE igdb_id = 17245 ON CONFLICT (game_id, language_code) DO NOTHING;
