INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battletoads In Battlemaniacs', 'Battletoads in Battlemaniacs is a platforming beat ''em up. The game follows two Battletoads, Rash and Pimple, on a quest to stop Silas Volkmire and the evil Dark Queen from ruling over the world. Many of its levels are enhanced or remixed versions of levels from the original Battletoads, featuring similar mechanics and gameplay styles.' FROM games WHERE igdb_id = 18577 ON CONFLICT (game_id, language_code) DO NOTHING;
