INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 956 AND rs.code = 'ESRB' AND r.code = 'E' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', true, false, true FROM games WHERE igdb_id = 956 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bio-menace', 8491, '1993-08-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co507b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qie0mt39pqewdb48zqgv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bio Menace', 'Intelligence reports indicate that a man calling himself Dr. Mangle is responsible for the mutants and the destruction of Metro. You will have to battle your way through levels packed with evil mutants and robotic guards to finally infiltrate Mangle''s fortress and defeat him. You think to yourself that this will be the most dangerous mission of your life. Snake Logan is a weapons expert, and uses several throughout the game, including a high-powered machine gun and grenades.' FROM games WHERE igdb_id = 8491 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 8491 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 8491 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 8491 AND c.slug = 'apogee-software' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 8491 AND c.slug = 'wiz-technology' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 8491 AND p.igdb_id = 3 ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 8491 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 8491 AND p.igdb_id = 13 ON CONFLICT DO NOTHING;
